INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-ush-early_q1', 'ap-topic-ush-early', 1, false, 'B', 'US History', 'easy', 'Which 1803 Supreme Court case established the principle of judicial review?', '["McCulloch v. Maryland","Marbury v. Madison","Dred Scott v. Sandford","Plessy v. Ferguson"]'::jsonb, 'Chief Justice John Marshall established judicial review in Marbury v. Madison.'),
  ('ap-topic-ush-early_q2', 'ap-topic-ush-early', 2, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'How did Bacon''s Rebellion (1676) in colonial Virginia accelerate the transition from indentured servitude to chattel slavery in the Chesapeake?', '["Chesapeake planters increasingly viewed landless former indentured servants as a dangerous source of social instability and turned to hereditary racial slavery as a more controllable labor force","The British Crown passed legislation completely banning European indentured servants from migrating to the Americas","Indentured servants voluntarily purchased their own African enslaved laborers to work Virginia plantations","The rebellion eliminated all tobacco cultivation, replacing it with small family subsistence farming"]'::jsonb, 'Bacon''s Rebellion united poor white indentured servants and enslaved Africans against Virginia''s planter elite. In response, wealthy planters transitioned decisively to racialized African chattel slavery to prevent future multiracial lower-class uprisings.'),
  ('ap-topic-ush-early_q3', 'ap-topic-ush-early', 3, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'What fundamental British policy shift following the French and Indian War (1763) triggered colonial resistance leading to the American Revolution?', '["The end of salutary neglect and Britain''s imposition of direct parliamentary taxes on the colonies to pay imperial war debts","Britain''s decision to cede all North American colonies to the French Crown","The immediate abolition of colonial legislative assemblies by royal decree","The total ban on transatlantic commerce between Britain and the thirteen colonies"]'::jsonb, 'Victory in the Seven Years'' War left Britain with massive debt. Parliament abandoned salutary neglect and enacted direct taxes (Sugar Act, Stamp Act) without colonial legislative representation.'),
  ('ap-topic-ush-early_q4', 'ap-topic-ush-early', 4, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'Why did Shays'' Rebellion (1786-1787) convince national leaders like George Washington and Alexander Hamilton that the Articles of Confederation were inadequate?', '["The Confederation Congress lacked the constitutional authority and military capability to raise troops or provide national security against domestic insurrection","The rebellion proved that state governors possessed too much military power over the central government","The insurrection was secretly funded by the British military to conquer Massachusetts","Congress had excessive power to confiscate small private farms without trial"]'::jsonb, 'Shays'' Rebellion exposed the fatal structural weaknesses of the Articles of Confederation: the central government had no executive branch, no power to levy taxes, and no standing military to suppress internal insurrections.'),
  ('ap-topic-ush-early_q5', 'ap-topic-ush-early', 5, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'How did the Great Compromise (Connecticut Compromise) resolve the dispute between large and small states at the 1787 Constitutional Convention?', '["It established a bicameral legislature with proportional representation in the House and equal representation in the Senate","It granted each state representation strictly based on its taxable wealth","It eliminated state boundaries in favor of three national administrative districts","It gave the President unilateral power to veto all state legislative acts"]'::jsonb, 'The Connecticut Compromise reconciled the Virginia Plan (proportional to population) and New Jersey Plan (equal per state) by creating a bicameral Congress: proportional in the House and equal (2 senators per state) in the Senate.'),
  ('ap-topic-ush-early_q6', 'ap-topic-ush-early', 6, false, 'A', 'Colonial Era to Reconstruction', 'hard', 'What constitutional principle did Chief Justice John Marshall establish in the landmark Supreme Court ruling *Marbury v. Madison* (1803)?', '["Judicial review: the Supreme Court holds the ultimate authority to declare acts of Congress unconstitutional","States have the sovereign constitutional power to nullify federal legislation within their borders","The President possesses absolute executive privilege over all congressional subpoenas","Congress has unlimited power to tax state banks under the Necessary and Proper Clause"]'::jsonb, 'In *Marbury v. Madison*, Marshall ruled that Section 13 of the Judiciary Act of 1789 violated Article III, establishing the foundational precedent of judicial review.'),
  ('ap-topic-ush-early_q7', 'ap-topic-ush-early', 7, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'How did the Missouri Compromise of 1820 attempt to maintain sectional balance regarding the expansion of slavery?', '["It admitted Missouri as a slave state and Maine as a free state, banning slavery in remaining Louisiana Purchase territory north of $36^\\circ 30''$ latitude","It outlawed the domestic slave trade across all state borders","It established popular sovereignty in all newly acquired Western territories","It required all slave states to enact gradual emancipation laws by 1850"]'::jsonb, 'Crafted by Henry Clay, the 1820 compromise admitted Missouri (slave) and Maine (free) to preserve the 12-to-12 Senate balance, while barring slavery in the unorganized Louisiana territory north of $36^\circ 30''N$.'),
  ('ap-topic-ush-early_q8', 'ap-topic-ush-early', 8, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'What was the primary assertion of the Monroe Doctrine issued by President James Monroe in 1823?', '["The Western Hemisphere was closed to future European colonization and European political intervention would be viewed as hostile acts","The United States would militarily intervene to annex Spanish colonies in South America","European powers were invited to arbitrate border disputes across North America","The United States pledged to participate directly in European military alliances"]'::jsonb, 'The Monroe Doctrine warned European monarchies that the American continents were no longer subjects for future European colonization and declared that European interference in the Americas was a threat to US peace and safety.'),
  ('ap-topic-ush-early_q9', 'ap-topic-ush-early', 9, false, 'A', 'Colonial Era to Reconstruction', 'hard', 'During the Nullification Crisis (1832-1833), what argument did John C. Calhoun advance in the *South Carolina Exposition and Protest*?', '["Sovereign states possessed the constitutional authority to declare federal tariffs null and void within their borders because the Union was a compact among states","The federal judiciary was the sole legitimate body to adjudicate disagreements over federal taxation","Industrial manufacturers in the North should be subject to direct federal taxation to subsidize Southern cotton exports","Enslaved laborers should be counted as full citizens for congressional apportionment"]'::jsonb, 'Calhoun argued the "compact theory" of the Constitution: because sovereign states formed the Union, an individual state convention had the right to nullify an unconstitutional federal law (the Tariff of Abominations) within its territory.'),
  ('ap-topic-ush-early_q10', 'ap-topic-ush-early', 10, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'Which antebellum reform movement produced the Declaration of Sentiments at the Seneca Falls Convention (1848)?', '["Women''s rights movement","Temperance movement","Abolitionist movement","Public asylum reform movement"]'::jsonb, 'Organized by Elizabeth Cady Stanton and Lucretia Mott, the Seneca Falls Convention adopted the Declaration of Sentiments, modeled on the Declaration of Independence, proclaiming "all men and women are created equal" and demanding women''s suffrage.'),
  ('ap-topic-ush-early_q11', 'ap-topic-ush-early', 11, false, 'A', 'Colonial Era to Reconstruction', 'hard', 'How did the Kansas-Nebraska Act (1854), authored by Stephen A. Douglas, fundamentally alter national policy regarding the western expansion of slavery?', '["It repealed the Missouri Compromise line and opened territories north of $36^\\circ 30''$ to slavery through popular sovereignty","It banned slavery in all territories acquired from Mexico","It mandated the immediate admission of Kansas as a slave state without territorial elections","It compensated Southern slaveholders for emancipating enslaved people migrating to Nebraska"]'::jsonb, 'Douglas''s bill repealed the 1820 Missouri Compromise ban on slavery north of $36^\circ 30''$, replacing it with "popular sovereignty" (letting territorial voters decide), which triggered violent clashes ("Bleeding Kansas") and birthed the Republican Party.'),
  ('ap-topic-ush-early_q12', 'ap-topic-ush-early', 12, false, 'A', 'Colonial Era to Reconstruction', 'hard', 'In the notorious *Dred Scott v. Sandford* (1857) ruling, Chief Justice Roger Taney held that:', '["African Americans were not citizens, and Congress had no constitutional power to prohibit slavery in federal territories","Enslaved individuals became legally free as soon as they set foot on free state soil","The Fugitive Slave Act of 1850 was unconstitutional under the Fourth Amendment","Popular sovereignty was the only legal mechanism to restrict slavery in territories"]'::jsonb, 'Taney ruled that Black Americans were not citizens and had "no rights which the white man was bound to respect." Furthermore, he declared the Missouri Compromise unconstitutional under the 5th Amendment, holding that Congress could not deprive slaveholders of property in federal territories.'),
  ('ap-topic-ush-early_q13', 'ap-topic-ush-early', 13, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'What immediate legal effect did President Abraham Lincoln''s Emancipation Proclamation (effective January 1, 1863) have?', '["It declared forever free all enslaved people in Confederate areas currently in active rebellion against the United States","It emancipated all enslaved people nationwide, including in loyal Border States","It compensated slaveholders in Maryland and Kentucky for voluntary emancipation","It granted immediate voting rights to all formerly enslaved men"]'::jsonb, 'Issued as a wartime military measure under presidential powers, the Proclamation freed enslaved people specifically in Confederate areas in rebellion. It excluded the loyal border states (MD, DE, KY, MO) and Union-controlled Southern areas.'),
  ('ap-topic-ush-early_q14', 'ap-topic-ush-early', 14, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'Which constitutional amendment ratified during Reconstruction guaranteed equal protection of the laws and citizenship to all persons born or naturalized in the United States?', '["Fourteenth Amendment","Thirteenth Amendment","Fifteenth Amendment","Sixteenth Amendment"]'::jsonb, 'The Fourteenth Amendment (1868) granted birthright citizenship (nullifying *Dred Scott*) and prohibited states from depriving any person of life, liberty, or property without due process of law or denying equal protection.'),
  ('ap-topic-ush-early_q15', 'ap-topic-ush-early', 15, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'What political bargain formally brought an end to Congressional Reconstruction in the South?', '["The Compromise of 1877, in which Rutherford B. Hayes was awarded the presidency in exchange for withdrawing all remaining federal troops from the South","The assassination of Abraham Lincoln by John Wilkes Booth","The ratification of the Thirteenth Amendment outlawing slavery","The impeachment and conviction of President Andrew Johnson"]'::jsonb, 'The disputed 1876 presidential election was resolved by the Compromise of 1877: Southern Democrats accepted Republican Hayes''s presidency in return for removing federal occupation troops, allowing white Democrats to re-establish home rule ("Redemption").'),
  ('ap-topic-ush-early_q16', 'ap-topic-ush-early', 16, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'What agricultural labor system predominated across the American South following the Civil War, trapping many freedpeople in persistent cycles of debt?', '["Sharecropping","Indentured servitude","Communal cooperative farming","Industrial wage labor"]'::jsonb, 'Lacking capital and land, freedpeople worked plots owned by white planters in exchange for a share (often 50%) of the harvested crop. Crop-lien debt and dishonest accounting kept most sharecroppers bound to the land.'),
  ('ap-topic-ush-early_q17', 'ap-topic-ush-early', 17, false, 'A', 'Colonial Era to Reconstruction', 'hard', 'Why did the Antifederalists vigorously oppose the ratification of the unamended 1787 United States Constitution?', '["They feared the powerful central government would erode individual liberties and state sovereignty, demanding a Bill of Rights","They desired an absolute hereditary monarchy modeled on Great Britain","They wanted to ban all interstate commerce and foreign trade","They objected to giving small states equal representation in the Senate"]'::jsonb, 'Antifederalists (such as Patrick Henry and George Mason) argued that the Constitution lacked explicit guarantees of basic individual rights and concentrated excessive power in the federal executive and judiciary at the expense of state autonomy.'),
  ('ap-topic-ush-early_q18', 'ap-topic-ush-early', 18, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'What was the central ideological vision articulated in Alexander Hamilton''s 1790-1791 financial reports to Congress?', '["Establishing a national bank, funding the national debt at par, assuming state debts, and promoting commercial manufacturing","Dismantling federal taxation and promoting an agrarian republic of self-sufficient yeoman farmers","Repudiating all state and federal debts incurred during the Revolutionary War","Eliminating all protective tariffs to encourage complete free trade with France"]'::jsonb, 'Hamilton''s financial program sought to tie wealthy creditors to national success by funding debt at par, assuming state debts, chartering the First Bank of the United States, and enacting protective tariffs to foster industrial capitalism.'),
  ('ap-topic-ush-early_q19', 'ap-topic-ush-early', 19, false, 'A', 'Colonial Era to Reconstruction', 'medium', 'Which transportation innovation in the 1820s dramatically lowered shipping costs between the Old Northwest agricultural region and New York City?', '["Erie Canal","Transcontinental Railroad","Cumberland National Road","Interstate highway system"]'::jsonb, 'Completed in 1825, the Erie Canal linked Lake Erie to the Hudson River, cutting freight costs by over 90% and establishing New York City as the preeminent commercial hub of the United States.'),
  ('ap-topic-ush-early_q20', 'ap-topic-ush-early', 20, false, 'A', 'Colonial Era to Reconstruction', 'hard', 'In his 1796 Farewell Address, what primary domestic and foreign pitfalls did George Washington warn the American public against?', '["The dangers of regional sectionalism, hyper-partisan political factions, and permanent foreign political alliances","The dangers of building a national navy and establishing commercial trade with Britain","The danger of admitting new western states to the Union","The threat posed by universal white male suffrage"]'::jsonb, 'Washington cautioned Americans against geographic factionalism, entangling permanent European alliances ("steer clear of permanent alliances"), and the baneful effects of party factional spirit.'),
  ('ap-topic-world-global_q1', 'ap-topic-world-global', 1, false, 'B', 'World History', 'easy', 'Which major trade route connected East Asia with the Mediterranean world during the post-classical era?', '["Trans-Saharan Route","Silk Roads","Hanseatic League","Amber Road"]'::jsonb, 'The Silk Roads facilitated Eurasian trade and cultural exchange.'),
  ('ap-topic-world-global_q2', 'ap-topic-world-global', 2, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'How did the introduction of Champa rice from Vietnam impact Song Dynasty China (960-1279 CE)?', '["It matured rapidly and resisted drought, allowing double-cropping and spurring massive agricultural surpluses and demographic expansion","It caused severe soil erosion that collapsed agricultural production in the Yangtze River valley","It was banned by Confucian scholar-officials as an unwholesome foreign grain","It forced Chinese peasants to abandon rice cultivation in favor of nomadic pastoralism"]'::jsonb, 'Champa rice was drought-resistant, ripened quickly (60 days), and permitted two harvests per year, fueling the Song economic revolution and a population boom exceeding 100 million.'),
  ('ap-topic-world-global_q3', 'ap-topic-world-global', 3, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'What institutional mechanism did the Song Dynasty rely upon to staff its imperial bureaucracy with educated administrators?', '["The imperial civil service examination system based on Confucian classics","Hereditary aristocratic military appointments","Direct selection by Buddhist monastic orders","Democratic elections held in provincial capitals"]'::jsonb, 'The Song expanded the merit-based civil service exam (keju) testing mastery of Neo-Confucian texts, producing a scholar-gentry bureaucratic elite that subordinated military nobility.'),
  ('ap-topic-world-global_q4', 'ap-topic-world-global', 4, false, 'A', 'Global Tapestry & Trade Networks', 'hard', 'What was the primary scholarly contribution of the House of Wisdom (Bayt al-Hikma) established in Baghdad during the Abbasid Caliphate?', '["Translating, synthesizing, and expanding scientific, mathematical, and philosophical texts from Greek, Persian, and Indian traditions into Arabic","Creating a standardized military code that suppressed European trade","Developing iron smelting technologies borrowed exclusively from sub-Saharan Africa","Printing the first religious texts in moveable type"]'::jsonb, 'The Abbasid House of Wisdom served as a premier intellectual center during the Islamic Golden Age, preserving classical Hellenistic, Persian, and Indian knowledge while advancing algebra, optics, and medicine.'),
  ('ap-topic-world-global_q5', 'ap-topic-world-global', 5, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'How did monsoon wind patterns shape trade in the Indian Ocean maritime network prior to 1450 CE?', '["Merchants sailed northeast in spring/summer and southwest in winter, residing in port cities for months and fostering diasporic merchant communities","Monsoon winds were too violent to allow regular maritime trade across the Arabian Sea","Winds blew steadily in only one direction year-round, preventing round-trip voyages","Ships were forced to hug coastlines exclusively using rowed galleys"]'::jsonb, 'Predictable seasonal monsoon winds dictated Indian Ocean sailing schedules. While waiting for wind reversals, Arab, Persian, and Chinese merchants settled in port enclaves, spreading Islam and intermarrying.'),
  ('ap-topic-world-global_q6', 'ap-topic-world-global', 6, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'What was the economic consequence of Mansa Musa''s famous hajj pilgrimage to Mecca in 1324?', '["His lavish gifts and spending of gold in Cairo and Mecca caused regional currency inflation that lasted for over a decade","His empire in Mali was completely bankrupted, collapsing the Trans-Saharan gold trade","He converted the Kingdom of Mali from Islam to Roman Catholicism","He signed a military alliance with the Holy Roman Empire"]'::jsonb, 'Mansa Musa distributed immense quantities of gold during his pilgrimage, famously devaluing gold in Cairo for years while placing Mali''s wealth on European maps (e.g., the Catalan Atlas).'),
  ('ap-topic-world-global_q7', 'ap-topic-world-global', 7, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'How did the Pax Mongolica (13th-14th centuries) facilitate Afro-Eurasian trade along the Silk Roads?', '["Unified Mongol political rule secured travel routes, protected merchants with passports (paiza), and established the postal relay system (Yam)","The Mongols forced all merchants to convert to Tibetan Buddhism to trade","The Mongols eliminated all maritime trade routes across the Indian Ocean","The Mongols outlawed the use of paper currency across Eurasia"]'::jsonb, 'The Mongol peace unified Eurasia under common legal protection (Yassa), police patrols, caravanserai networks, and the Yam postal/courier system, drastically reducing transaction costs for long-distance merchants like Marco Polo and Ibn Battuta.'),
  ('ap-topic-world-global_q8', 'ap-topic-world-global', 8, false, 'A', 'Global Tapestry & Trade Networks', 'hard', 'What agricultural engineering system enabled the Aztec (Mexica) Empire to sustain a dense population in the Valley of Mexico?', '["Chinampas (floating artificial agricultural islands)","Terrace farming cut into Andean peaks","Underground qanat irrigation canals","Inundation flood basins along the Nile"]'::jsonb, 'The Aztecs constructed chinampas: artificial islands built of mud, reeds, and decomposing organic matter in shallow lake beds, allowing continuous multi-crop harvesting around Tenochtitlan.'),
  ('ap-topic-world-global_q9', 'ap-topic-world-global', 9, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'What was the mita system utilized by the Inca Empire before Spanish colonization?', '["A mandatory reciprocal labor tribute service that subjects provided to the imperial state for public infrastructure and road construction","A monetary tax paid exclusively in silver bullion","A human sacrifice ritual performed on all conquered nobility","A trade network conducted strictly with Polynesian voyagers"]'::jsonb, 'The Inca mita was a rotational labor obligation requiring communities to build roads, bridges, storehouses, and terraced fields for the state, which in turn redistributed food during famines.'),
  ('ap-topic-world-global_q10', 'ap-topic-world-global', 10, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'Which commercial financial innovations developed in China during the Tang and Song dynasties facilitated long-distance trade without transporting bulky copper coins?', '["\"Flying cash\" (credit paper receipts) and the world''s first government-issued paper money (Jiaozi)","Joint-stock corporate charters backed by British royal decree","Cryptographic distributed ledgers recorded on bamboo strips","Gold standard certificates minted by Islamic caliphs"]'::jsonb, 'The Song economy introduced "flying cash" (feiqian), a credit deposit receipt allowing merchants to deposit coin in the capital and withdraw cash in distant provinces, culminating in early paper currency (jiaozi).'),
  ('ap-topic-world-global_q11', 'ap-topic-world-global', 11, false, 'A', 'Global Tapestry & Trade Networks', 'hard', 'What was the primary motive behind the Ming Dynasty''s grand maritime expeditions commanded by Admiral Zheng He in the early 15th century?', '["To project Ming prestige, demonstrate imperial supremacy, and enroll foreign rulers into China''s tributary system","To conquer and colonize the east coast of Africa for timber extraction","To find an all-water passage to the Americas for silver mining","To escape a Mongol invasion of the southern coastal provinces"]'::jsonb, 'Commissioned by the Yongle Emperor, Zheng He''s treasure fleet voyages (1405-1433) were diplomatic displays of power designed to enforce the tributary system and control trade, not to establish territorial colonies.'),
  ('ap-topic-world-global_q12', 'ap-topic-world-global', 12, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'What was the Ottoman Empire''s devshirme system?', '["The recruitment of young Christian boys from the Balkans who were converted to Islam, educated, and trained as elite Janissary soldiers and imperial bureaucrats","A land tax levied exclusively on Muslim merchants trading in Constantinople","A diplomatic treaty dividing maritime trade between Venice and the Ottomans","A military alliance between the Ottoman Empire and the Safavid Dynasty"]'::jsonb, 'The devshirme ("blood tax" or collection) enlisted Balkan Christian youths into state service, raising an elite military corps (Janissaries) and civil administrators fiercely loyal directly to the Sultan.'),
  ('ap-topic-world-global_q13', 'ap-topic-world-global', 13, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'How did Mughal Emperor Akbar (reigned 1556-1605) seek to consolidate imperial rule over a religiously diverse Hindu majority in India?', '["He abolished the jizya tax on non-Muslims, welcomed Hindus into senior government positions, and promoted religious tolerance","He forced all Hindu subjects to convert to Sunni Islam under penalty of exile","He expelled European Christian Jesuit missionaries from the subcontinent","He outlawed all religious discussions at court"]'::jsonb, 'Akbar pursued policy of sulh-i kul (universal peace), repealing the discriminatory jizya tax, marrying Rajput Hindu princesses, patronizing Hindu scholars, and holding interfaith dialogues in the Ibadat Khana.'),
  ('ap-topic-world-global_q14', 'ap-topic-world-global', 14, false, 'A', 'Global Tapestry & Trade Networks', 'hard', 'How did the global flow of American silver (from Potosí and Zacatecas) transform the Ming Chinese economy in the 16th and 17th centuries?', '["The Ming Single Whip tax reform required taxes to be paid exclusively in silver, making China the ultimate global sink for world silver","Silver was declared illegal, forcing Chinese merchants to barter with tea","The influx of silver caused Ming China to abandon trade with Spanish Manila","American silver led China to abolish all overseas porcelain and silk production"]'::jsonb, 'Under the Single Whip reform, China monetized its tax system in silver. European and Japanese merchants exchanged vast quantities of American silver in Manila and Macau to buy Chinese silk, porcelain, and tea.'),
  ('ap-topic-world-global_q15', 'ap-topic-world-global', 15, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'Which of the following was an American crop transferred to the Eastern Hemisphere as part of the Columbian Exchange that drastically increased caloric yields in Europe and Asia?', '["Potato","Wheat","Sugarcane","Coffee"]'::jsonb, 'Potatoes, maize, sweet potatoes, and cassava were New World domesticates that provided dense calories and grew well in marginal soils, driving major population growth across Eurasia.'),
  ('ap-topic-world-global_q16', 'ap-topic-world-global', 16, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'Why were Afro-Eurasian epidemic diseases (such as smallpox and measles) so catastrophic for Indigenous American populations after 1492?', '["Indigenous peoples had lived in complete isolation from Afro-Eurasian livestock pathogens and possessed zero acquired immunological resistance","Indigenous populations had access to no fresh water sources","American climates caused pathogens to mutate into incurable airborne toxins","Spanish conquerors vaccinated themselves while denying food to local communities"]'::jsonb, 'Having had no previous contact with European and African zoonotic crowd diseases, Indigenous Americans lacked inherited immunities, leading to virgin-soil epidemics that killed 50-90% of the native population.'),
  ('ap-topic-world-global_q17', 'ap-topic-world-global', 17, false, 'A', 'Global Tapestry & Trade Networks', 'hard', 'What characterized the syncretic Swahili city-states along the East African coast between 1200 and 1450 CE?', '["A hybrid culture combining Bantu language foundations with Arabic loanwords, Islamic faith, and Indian Ocean commerce","A landlocked empire governed by Ethiopian Christian emperors","A strictly nomadic pastoralist culture rejecting trade and seafaring","A Portuguese colony dominated entirely by Roman Catholic clergy"]'::jsonb, 'Swahili city-states (Kilwa, Mombasa, Zanzibar) blended indigenous Bantu roots with Arab-Islamic mercantile influences, developing the Swahili language and trading gold, ivory, and timber across the Indian Ocean.'),
  ('ap-topic-world-global_q18', 'ap-topic-world-global', 18, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'How did joint-stock companies, such as the Dutch East India Company (VOC), revolutionize early modern global commerce?', '["They pooled capital from private investors, spread liability risks, and exercised sovereign powers including maintaining private armies and minting currency","They were non-profit charities dedicated solely to funding religious missions","They eliminated all private investment in favor of direct monarchical ownership","They traded exclusively within European domestic borders"]'::jsonb, 'Joint-stock companies allowed thousands of shareholders to pool capital with limited liability. The VOC was granted quasi-governmental charters to wage war, build forts, negotiate treaties, and monopolize the spice trade.'),
  ('ap-topic-world-global_q19', 'ap-topic-world-global', 19, false, 'A', 'Global Tapestry & Trade Networks', 'hard', 'What theological dispute caused the bitter geopolitical rivalry between the Ottoman and Safavid Empires in the 16th century?', '["The Ottomans championed Sunni Islam, while the Safavids instituted Twelver Shi''ism as their compulsory state religion","The Ottomans were Orthodox Christians while the Safavids were Roman Catholics","The Safavids adopted Theravada Buddhism as their state ideology","The Ottomans demanded the complete eradication of the Persian language"]'::jsonb, 'Shah Ismail established Twelver Shi''ism as the mandatory state faith of the Safavid Empire, directly clashing with the Sunni Ottoman Caliphate in territorial and ideological wars (e.g., the Battle of Chaldiran, 1514).'),
  ('ap-topic-world-global_q20', 'ap-topic-world-global', 20, false, 'A', 'Global Tapestry & Trade Networks', 'medium', 'What was the primary impact of the Trans-Saharan camel caravan trade on West African kingdoms like Ghana and Mali?', '["It exchanged West African gold and slaves for North African salt, manufactured textiles, and horses, while spreading Islamic literacy and legal codes","It led to the immediate conquest of West Africa by the Roman Empire","It depleted all West African gold within twenty years, ending regional urbanization","It isolated West Africa completely from Mediterranean trade"]'::jsonb, 'The camel saddle enabled regular desert crossings. West African kingdoms grew wealthy by taxing the trade in southern gold and forest goods exchanged for northern Saharan salt, bringing Islamic scholarship and Arabic writing.'),
  ('ap-topic-euro-ren_q1', 'ap-topic-euro-ren', 1, false, 'B', 'European History', 'medium', 'In 1517, Martin Luther nailed which document to the door of Wittenberg Castle Church?', '["Edict of Worms","95 Theses","Peace of Augsburg","Institutes of Christian Religion"]'::jsonb, 'The 95 Theses criticized papal indulgences and sparked the Protestant Reformation.'),
  ('ap-topic-euro-ren_q2', 'ap-topic-euro-ren', 2, false, 'A', 'Renaissance & Reformation', 'medium', 'What core philosophical philosophy distinguished Renaissance humanism from medieval scholasticism?', '["Humanism emphasized the study of classical Greek and Latin literature, rhetoric, and human potential rather than scholastic theological syllogisms","Humanism completely rejected religious belief in favor of radical scientific atheism","Humanism advocated for the immediate dissolution of all organized civil governments","Humanism focused exclusively on manual agricultural labor techniques"]'::jsonb, 'Renaissance humanism (the *studia humanitatis*) revived classical Greco-Roman texts, grammar, poetry, and moral philosophy, emphasizing secular human dignity and civic participation over medieval scholastic abstractions.'),
  ('ap-topic-euro-ren_q3', 'ap-topic-euro-ren', 3, false, 'A', 'Renaissance & Reformation', 'medium', 'In *The Prince* (1513), Niccolò Machiavelli argued that a ruler''s primary objective should be:', '["Maintaining state political power and stability by pragmatic means, recognizing that it is safer to be feared than loved","Governing strictly in accordance with Christian pacifist virtues and biblical charity","Surrendering sovereign power to the Roman Catholic Papacy","Establishing a direct democracy with universal suffrage"]'::jsonb, 'Machiavelli detached politics from traditional morality, arguing that statecraft requires realism (*realpolitik*): a prince must prioritize the preservation of order and power using force and cunning (*virtù*).'),
  ('ap-topic-euro-ren_q4', 'ap-topic-euro-ren', 4, false, 'A', 'Renaissance & Reformation', 'medium', 'How did Northern Renaissance humanists like Desiderius Erasmus differ from Italian humanists?', '["Northern humanists focused on Christian humanism, applying classical philological scholarship to biblical reform and moral renewal","Northern humanists completely rejected the study of Greek and Latin languages","Northern humanists advocated violent rebellion against all monarchical rulers","Northern humanists focused solely on pagan mythology and secular civic politics"]'::jsonb, 'Christian humanism in the North (Erasmus, Thomas More) synthesized classical humanist scholarship with early church scripture to reform religious morality, critique Catholic abuses, and promote inner piety.'),
  ('ap-topic-euro-ren_q5', 'ap-topic-euro-ren', 5, false, 'A', 'Renaissance & Reformation', 'medium', 'What revolutionary technology, developed in Mainz around 1450 by Johannes Gutenberg, accelerated the dissemination of Renaissance and Reformation ideas?', '["Moveable metal type printing press","Mechanical clockwork calculators","Paper mills using steam engines","Woodblock stamping on silk"]'::jsonb, 'Gutenberg''s moveable metal type printing press drastically reduced book production costs, increased literacy, and enabled rapid, widespread dissemination of Luther''s 95 Theses and Protestant pamphlets.'),
  ('ap-topic-euro-ren_q6', 'ap-topic-euro-ren', 6, false, 'A', 'Renaissance & Reformation', 'medium', 'What specific Catholic practice provoked Martin Luther to post his Ninety-Five Theses in Wittenberg in 1517?', '["The aggressive sale of papal indulgences by friars like Johann Tetzel to fund St. Peter''s Basilica","The Pope''s declaration of universal peace among all European monarchs","The requirement that all European peasants attend Latin masses weekly","The appointment of German princes to the College of Cardinals"]'::jsonb, 'Luther attacked the commercialized sale of indulgences (certificates claiming to reduce punishment for sins in Purgatory), arguing salvation is a free gift of God''s grace, not an ecclesiastical commodity.'),
  ('ap-topic-euro-ren_q7', 'ap-topic-euro-ren', 7, false, 'A', 'Renaissance & Reformation', 'hard', 'What were the two foundational theological tenets of Martin Luther''s Protestant doctrine?', '["*Sola fide* (justification by faith alone) and *sola scriptura* (the Bible as the sole authority in faith)","Papal infallibility and transubstantiation in seven sacraments","Double predestination and rule by theocratic consistory","Universal pacifism and adult rebaptism"]'::jsonb, 'Luther rejected Catholic salvation through faith and good works, asserting *sola fide* (salvation by faith alone through divine grace) and *sola scriptura* (Scripture alone as the ultimate source of spiritual truth, rejecting papal supremacy).'),
  ('ap-topic-euro-ren_q8', 'ap-topic-euro-ren', 8, false, 'A', 'Renaissance & Reformation', 'medium', 'Which central doctrine formed the cornerstone of John Calvin''s theological system in Geneva?', '["Predestination: God has eternally determined who is saved (the elect) and who is damned","Salvation through pilgrimage and penance","Rejection of the Holy Trinity","Belief in purgatorial purification for all believers"]'::jsonb, 'In *Institutes of the Christian Religion* (1536), Calvin emphasized the absolute sovereignty of God, arguing that God has pre-ordained from eternity who will receive salvation (the Elect) independently of human merit.'),
  ('ap-topic-euro-ren_q9', 'ap-topic-euro-ren', 9, false, 'A', 'Renaissance & Reformation', 'medium', 'What was the immediate catalyst for the English Reformation under King Henry VIII in the 1530s?', '["Pope Clement VII''s refusal to annul Henry VIII''s marriage to Catherine of Aragon","Henry VIII''s conversion to radical Anabaptist theology","A widespread peasant revolt demanding the confiscation of monastic lands","A French invasion that captured the Archbishop of Canterbury"]'::jsonb, 'Henry needed a male heir to secure the Tudor succession. When the Pope refused to annul his marriage to Catherine of Aragon (aunt of Emperor Charles V), Henry broke with Rome, passing the Act of Supremacy (1534).'),
  ('ap-topic-euro-ren_q10', 'ap-topic-euro-ren', 10, false, 'A', 'Renaissance & Reformation', 'medium', 'What major religious settlement established the principle of *cuius regio, eius religio* in the Holy Roman Empire in 1555?', '["Peace of Augsburg","Edict of Nantes","Treaty of Westphalia","Council of Trent"]'::jsonb, 'The Peace of Augsburg (1555) ended fighting between Emperor Charles V and Lutheran princes, establishing *cuius regio, eius religio* ("whose realm, his religion"): each prince chose Lutheranism or Catholicism for his territory.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-euro-ren_q11', 'ap-topic-euro-ren', 11, false, 'A', 'Renaissance & Reformation', 'hard', 'How did the Council of Trent (1545-1563) respond to Protestant theological challenges during the Catholic Counter-Reformation?', '["It reaffirmed all core Catholic doctrines and the seven sacraments while enacting strict institutional reforms to end clerical corruption and improve clergy education","It accepted Luther''s doctrine of justification by faith alone","It abolished the authority of the Pope and dissolved monastic orders","It legalized clerical marriage and vernacular scripture readings"]'::jsonb, 'The Council of Trent rejected Protestant compromises, reaffirming papal authority, tradition alongside scripture, and the seven sacraments, but reformed administrative abuses (simony, absenteeism) and established seminaries.'),
  ('ap-topic-euro-ren_q12', 'ap-topic-euro-ren', 12, false, 'A', 'Renaissance & Reformation', 'medium', 'Which new religious order founded by Ignatius of Loyola in 1540 became a spearhead for the Catholic Reformation through education and global missionary work?', '["Society of Jesus (Jesuits)","Franciscan Order","Dominican Order","Cistercian Order"]'::jsonb, 'The Jesuits took a vow of obedience to the Pope, establishing premier classical humanist colleges across Europe, reconverting Protestant regions (Poland, southern Germany), and proselytizing in Asia and the Americas.'),
  ('ap-topic-euro-ren_q13', 'ap-topic-euro-ren', 13, false, 'A', 'Renaissance & Reformation', 'medium', 'What was the historic significance of the Edict of Nantes issued by King Henry IV of France in 1598?', '["It granted French Calvinists (Huguenots) religious tolerance, freedom of conscience, and fortified safe-haven towns","It expelled all Protestants from French soil","It made Roman Catholicism the mandatory faith across all of Europe","It declared France an independent Protestant republic"]'::jsonb, 'To end the devastating French Wars of Religion, the *politique* monarch Henry IV issued the Edict of Nantes, granting Huguenots rights of worship and fortified towns (like La Rochelle).'),
  ('ap-topic-euro-ren_q14', 'ap-topic-euro-ren', 14, false, 'A', 'Renaissance & Reformation', 'hard', 'How did the Peace of Westphalia (1648) concluding the Thirty Years'' War transform the political structure of Europe?', '["It recognized the sovereign equality of independent states, added Calvinism to acceptable religions, and permanently weakened the Holy Roman Empire","It unified Germany under the absolute monarchy of the Austrian Habsburgs","It restored papal authority over all European diplomacy","It dissolved the Dutch Republic and returned it to Spanish control"]'::jsonb, 'Westphalia marked the birth of modern international relations: sovereign states determine their own domestic affairs (including religion), Calvinism was recognized, Swiss/Dutch independence was confirmed, and central Habsburg imperial control fractured.'),
  ('ap-topic-euro-ren_q15', 'ap-topic-euro-ren', 15, false, 'A', 'Renaissance & Reformation', 'medium', 'Why did Martin Luther fiercely condemn the German Peasants'' Revolt (1524-1525) in his tract *Against the Murderous, Thieving Hordes of Peasants*?', '["Luther believed spiritual freedom in Christ did not justify temporal social revolution or defiance of ordained secular political rulers","The peasants demanded the restoration of papal authority in Germany","Luther supported the complete abolition of private property by the nobility","The peasants refused to read Luther''s German translation of the Bible"]'::jsonb, 'Luther viewed secular rulers as ordained by God to maintain earthly order. Fearing social anarchy would destroy the religious Reformation, he urged princes to ruthlessly suppress peasant social rebellion.'),
  ('ap-topic-euro-ren_q16', 'ap-topic-euro-ren', 16, false, 'A', 'Renaissance & Reformation', 'medium', 'Which visual artistic technique, perfected during the Italian Renaissance by artists such as Brunelleschi and Masaccio, created the illusion of 3-dimensional depth on a flat surface?', '["Linear perspective using a vanishing point","Chiaroscuro without geometric guidelines","Hieratic scaling based on social rank","Iconographic flat mosaic layering"]'::jsonb, 'Filippo Brunelleschi formulated mathematical linear perspective, using orthogonal lines converging at a single vanishing point on the horizon to accurately depict 3D space on a 2D surface.'),
  ('ap-topic-euro-ren_q17', 'ap-topic-euro-ren', 17, false, 'A', 'Renaissance & Reformation', 'hard', 'What radical Protestant group rejected infant baptism, practiced strict pacifism, and advocated the complete separation of church and state?', '["Anabaptists","Anglicans","Lutherans","Presbyterians"]'::jsonb, 'Anabaptists ("rebaptizers") held that true baptism required adult confession of faith. They refused to bear arms, swear oaths to civil magistrates, or participate in secular government, leading to persecution by Catholics and mainstream Protestants alike.'),
  ('ap-topic-euro-ren_q18', 'ap-topic-euro-ren', 18, false, 'A', 'Renaissance & Reformation', 'medium', 'What economic theory dominated European imperial policy from the 16th to 18th centuries, holding that national power depended on accumulating bullion by maximizing exports and minimizing imports?', '["Mercantilism","Laissez-faire capitalism","Physiocracy","Utopian socialism"]'::jsonb, 'Mercantilism viewed global wealth as a finite zero-sum game. Nations used protective tariffs, monopolies, and colonial extraction to maintain a positive balance of trade and stockpile gold and silver bullion.'),
  ('ap-topic-euro-ren_q19', 'ap-topic-euro-ren', 19, false, 'A', 'Renaissance & Reformation', 'medium', 'Which Italian city-state was the prominent financial and cultural cradle of the early Renaissance, largely due to the patronage of the Medici family?', '["Florence","Rome","Naples","Milan"]'::jsonb, 'Florence combined textile manufacturing and international banking (the Medici bank). Wealthy merchant patrons funded humanist scholars and revolutionary artists like Donatello, Botticelli, and Michelangelo.'),
  ('ap-topic-euro-ren_q20', 'ap-topic-euro-ren', 20, false, 'A', 'Renaissance & Reformation', 'hard', 'What was the primary argument in Baldassare Castiglione''s influential conduct manual *The Book of the Courtier* (1528)?', '["The ideal gentleman should cultivate well-rounded excellence (*l''uomo universale*) in classical learning, martial arts, music, and effortless grace (*sprezzatura*)","Nobles should abandon court life to become merchant bankers in Italian cities","Courtiers must obey every papal decree without personal moral discernment","Peasants should be given equal access to aristocratic titles"]'::jsonb, 'Castiglione defined the Renaissance "universal man" (courtier): educated in the humanities, skilled in conversation, diplomacy, arms, and fine arts, displaying effortless elegance (*sprezzatura*).'),
  ('ap-topic-macro-gdp_q1', 'ap-topic-macro-gdp', 1, false, 'C', 'Macroeconomics', 'easy', 'Unemployment caused by changes in the business cycle is called:', '["Frictional","Structural","Cyclical","Seasonal"]'::jsonb, 'Cyclical unemployment rises during economic downturns and recessions.'),
  ('ap-topic-macro-gdp_q2', 'ap-topic-macro-gdp', 2, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'Which transaction is included in the calculation of the United States Gross Domestic Product (GDP)?', '["A domestic consumer purchasing a newly manufactured haircut service in Chicago","The sale of a used 2015 automobile between two private individuals","A grandmother receiving her monthly federal Social Security benefit check","An American baker purchasing 50 pounds of intermediate flour to bake commercial bread"]'::jsonb, 'GDP includes only final goods and services produced domestically within a given time period. Used goods are excluded (already counted in the year of manufacture), transfer payments are excluded (no production occurred), and intermediate goods are excluded to avoid double-counting.'),
  ('ap-topic-macro-gdp_q3', 'ap-topic-macro-gdp', 3, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'If nominal GDP in an economy is $600\text{ billion}$ and the GDP deflator is 120, what is real GDP?', '["$500 billion","$720 billion","$480 billion","$600 billion"]'::jsonb, '$\text{Real GDP} = \frac{\text{Nominal GDP}}{\text{GDP Deflator}} \times 100 = \frac{\$600\text{ billion}}{120} \times 100 = \$500\text{ billion}$.'),
  ('ap-topic-macro-gdp_q4', 'ap-topic-macro-gdp', 4, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'An autoworker loses their job because robotic assembly arms permanently replace human welders on the manufacturing floor. What type of unemployment is this worker experiencing?', '["Structural unemployment","Frictional unemployment","Cyclical unemployment","Seasonal unemployment"]'::jsonb, 'Structural unemployment results from technological shifts or structural changes in the economy that render specific worker skills obsolete or misaligned with available jobs.'),
  ('ap-topic-macro-gdp_q5', 'ap-topic-macro-gdp', 5, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'In an economy with a Marginal Propensity to Consume ($MPC$) of 0.80, the government increases government spending by $\$50\text{ billion}$. By how much will equilibrium real GDP increase, assuming no crowding-out effect?', '["$250 billion","$200 billion","$100 billion","$50 billion"]'::jsonb, 'The spending multiplier is $M = \frac{1}{1 - MPC} = \frac{1}{1 - 0.80} = \frac{1}{0.20} = 5$. Total increase in GDP is $\Delta Y = M \times \Delta G = 5 \times \$50\text{ billion} = \$250\text{ billion}$.'),
  ('ap-topic-macro-gdp_q6', 'ap-topic-macro-gdp', 6, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'If the central bank increases the interest rate paid on reserve balances (IORB) under an ample-reserves monetary framework, what is the expected impact on short-term interest rates and aggregate demand?', '["Short-term interest rates rise, borrowing decreases, and aggregate demand shifts to the left","Short-term interest rates fall, investment spending surges, and aggregate demand shifts right","Commercial banks lend all reserves, causing rapid hyperinflation","There is zero impact on the policy rate or borrowing costs"]'::jsonb, 'Raising the IORB sets a higher reservation floor for interbank lending, pulling the policy federal funds rate upward. Higher market interest rates increase borrowing costs for firms and households, curtailing consumption and investment and shifting AD left.'),
  ('ap-topic-macro-gdp_q7', 'ap-topic-macro-gdp', 7, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'What happens to the Short-Run Aggregate Supply (SRAS) curve and the price level when a major international oil cartel unexpectedly cuts global crude oil production?', '["SRAS shifts to the left, causing cost-push inflation and higher price levels (stagflation)","SRAS shifts to the right, causing lower price levels and higher output","Aggregate Demand shifts to the right, creating demand-pull inflation","Long-Run Aggregate Supply shifts right because oil is conserved"]'::jsonb, 'A negative supply shock (sharp increase in critical input prices) increases production costs economy-wide, shifting SRAS leftward, resulting in higher price levels alongside contracting output (stagflation).'),
  ('ap-topic-macro-gdp_q8', 'ap-topic-macro-gdp', 8, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'Who benefits and who is harmed when the actual inflation rate is significantly higher than the anticipated (expected) inflation rate?', '["Borrowers on fixed-rate loans benefit; lenders and savers on fixed rates are harmed","Lenders benefit; borrowers are harmed","Both borrowers and lenders benefit equally","Neither party is affected because money is neutral"]'::jsonb, 'Unexpected inflation reduces the purchasing power of repaid dollars. Fixed-rate borrowers repay debts with cheaper dollars than lenders anticipated, transferring real purchasing power from creditors to debtors.'),
  ('ap-topic-macro-gdp_q9', 'ap-topic-macro-gdp', 9, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'According to the Long-Run Phillips Curve (LRPC), what is the relationship between the unemployment rate and the inflation rate in the long run?', '["There is no trade-off; the LRPC is vertical at the natural rate of unemployment","There is a persistent downward-sloping inverse relationship","Higher inflation permanently lowers the unemployment rate to zero","The curve is strictly horizontal at a 2% inflation target"]'::jsonb, 'In the long run, wages and prices are flexible. Anticipated inflation adjusts, returning output to potential GDP and unemployment to the natural rate (Non-Accelerating Inflation Rate of Unemployment, NAIRU). Thus the LRPC is vertical.'),
  ('ap-topic-macro-gdp_q10', 'ap-topic-macro-gdp', 10, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'How does an increase in national government budget deficits affect the loanable funds market and private domestic investment?', '["Government borrowing shifts demand for loanable funds right, increasing real interest rates and crowding out private investment","Government borrowing shifts supply of loanable funds right, reducing real interest rates","Private investment automatically increases due to increased sovereign credit","Real interest rates fall to zero"]'::jsonb, 'Deficit spending increases public borrowing, shifting loanable funds demand to the right. The equilibrium real interest rate rises, raising financing hurdles for private corporations and "crowding out" private capital investment.'),
  ('ap-topic-macro-gdp_q11', 'ap-topic-macro-gdp', 11, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'If real interest rates in the United States rise relative to those in the European Union, what will happen in the foreign exchange market for the US dollar ($) and US net exports ($X_n$)?', '["Capital flows into the US, increasing demand for dollars, causing the dollar to appreciate, which makes US exports more expensive and decreases net exports","Capital flees the US, causing the dollar to depreciate and increasing net exports","The dollar appreciates and net exports increase dramatically","Exchange rates remain unchanged because of purchasing power parity"]'::jsonb, 'Higher US real returns attract foreign financial capital. European investors convert euros to buy dollars, appreciating the USD. A stronger dollar makes American exports pricier abroad and imports cheaper, lowering US net exports.'),
  ('ap-topic-macro-gdp_q12', 'ap-topic-macro-gdp', 12, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'What combination of fiscal policy tools is appropriate to close an inflationary output gap?', '["Decreasing government purchases and increasing personal income taxes","Increasing government purchases and lowering business taxes","Lowering the policy interest rate and buying bonds","Increasing transfer payments to households"]'::jsonb, 'To cool an overheating economy operating beyond potential GDP, contractionary fiscal policy reduces aggregate demand by cutting government spending and/or raising taxes.'),
  ('ap-topic-macro-gdp_q13', 'ap-topic-macro-gdp', 13, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'Which of the following describes an automatic stabilizer in macroeconomic policy?', '["Progressive income tax revenues that automatically decline and unemployment compensation outlays that automatically rise during a recession without new legislation","Emergency stimulus checks voted on by Congress during a financial panic","The Federal Reserve chair announcing interest rate cuts at a press conference","A constitutional amendment requiring a balanced annual federal budget"]'::jsonb, 'Automatic stabilizers are pre-existing tax and transfer provisions that dampen business cycle swings without active legislative action: taxes fall and unemployment benefits expand automatically as GDP contracts.'),
  ('ap-topic-macro-gdp_q14', 'ap-topic-macro-gdp', 14, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'If the reserve requirement ratio is $10\%$ and the banking system operates with zero excess reserves and no currency leakage, what is the maximum increase in the money supply from a fresh $\$10,000$ cash deposit into a commercial checking account?', '["$90,000","$100,000","$10,000","$1,000"]'::jsonb, 'The bank must keep $10\% \times \$10,000 = \$1,000$ in required reserves, leaving $\$9,000$ in excess reserves to lend. The money multiplier is $m = \frac{1}{rr} = \frac{1}{0.10} = 10$. The maximum *new* credit money created by the banking system through loan expansion is $\$9,000 \times 10 = \$90,000$. (Total final checkable deposits will be $\$100,000$, representing $\$90,000$ in newly created money).'),
  ('ap-topic-macro-gdp_q15', 'ap-topic-macro-gdp', 15, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'What represents the natural rate of unemployment ($NRU$)?', '["The sum of frictional and structural unemployment when the economy is at potential output","Zero percent unemployment across all economic sectors","The unemployment rate when cyclical unemployment is at its peak","The percentage of workers who have permanently given up looking for work"]'::jsonb, 'The natural rate of unemployment occurs when the output gap is zero (full employment). Cyclical unemployment is zero, leaving only frictional unemployment (job search) and structural unemployment (skills transition).'),
  ('ap-topic-macro-gdp_q16', 'ap-topic-macro-gdp', 16, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'In the Classical view of long-run macroeconomic equilibrium, why is the Long-Run Aggregate Supply (LRAS) curve vertical at potential output $Y_f$?', '["Nominal wages and input prices are fully flexible in the long run, eliminating money illusion and restoring potential output","Technological innovation ceases to exist in the long run","Aggregate demand is determined entirely by government quotas","Firms produce identical quantities regardless of profitability"]'::jsonb, 'In the long run, input contracts and wages adjust completely to price level changes. Real profits and real wages return to baseline, leaving real output determined strictly by technology, capital, and labor resources.'),
  ('ap-topic-macro-gdp_q17', 'ap-topic-macro-gdp', 17, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'How is the Consumer Price Index (CPI) calculated relative to a base year?', '["$\\text{CPI} = \\frac{\\text{Cost of fixed market basket in current year}}{\\text{Cost of fixed market basket in base year}} \\times 100$","$\\text{CPI} = \\frac{\\text{Nominal GDP}}{\\text{Real GDP}} \\times 100$","$\\text{CPI} = \\frac{\\text{Total Government Spending}}{\\text{Total Tax Revenue}} \\times 100$","$\\text{CPI} = \\frac{\\text{Current Year Wage}}{\\text{Base Year Wage}} \\times 100$"]'::jsonb, 'CPI tracks the cost of a standardized consumer market basket purchased by an urban household over time: $\text{CPI} = \frac{\text{Cost in Current Year}}{\text{Cost in Base Year}} \times 100$.'),
  ('ap-topic-macro-gdp_q18', 'ap-topic-macro-gdp', 18, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'What is the relationship between the tax multiplier and the government spending multiplier?', '["The tax multiplier has a smaller absolute magnitude than the spending multiplier because part of a tax cut is saved ($MPS$) rather than spent","The tax multiplier is always exactly double the spending multiplier","The two multipliers are identical in magnitude and sign","The tax multiplier is always zero in the short run"]'::jsonb, 'Government purchases inject 100% of dollars directly into GDP, giving $M_g = \frac{1}{1-MPC}$. A tax cut increases disposable income, of which households save a fraction ($MPS$), so initial spending is only $MPC \times \Delta T$, making $M_t = -\frac{MPC}{1-MPC}$.'),
  ('ap-topic-macro-gdp_q19', 'ap-topic-macro-gdp', 19, false, 'A', 'GDP, Inflation & AD/AS', 'medium', 'What causes the downward slope of the Aggregate Demand (AD) curve?', '["The real wealth effect, the interest rate effect, and the foreign purchases effect","The law of diminishing marginal returns in manufacturing","Increasing substitution between domestic goods and foreign currency","Government regulations restricting factory output at higher price levels"]'::jsonb, 'Higher aggregate price levels reduce the real purchasing power of cash wealth (wealth effect), increase demand for money and raise interest rates (interest rate effect), and make domestic goods pricier than foreign goods (exchange/foreign purchases effect).'),
  ('ap-topic-macro-gdp_q20', 'ap-topic-macro-gdp', 20, false, 'A', 'GDP, Inflation & AD/AS', 'hard', 'According to the Quantity Theory of Money, $M \times V = P \times Y$. If velocity $V$ and real output $Y$ are constant in the long run, what is the consequence of a $10\%$ increase in the money supply $M$?', '["A $10\\%$ increase in the price level $P$ (proportional inflation)","A $10\\%$ increase in real output $Y$","A $10\\%$ decline in velocity $V$","Zero change in price level or nominal GDP"]'::jsonb, 'With $V$ and $Y$ held constant, the equation of exchange dictates $\%\Delta M = \%\Delta P$. A $10\%$ expansion in money supply yields an exact $10\%$ inflation rate in the price level (monetary neutrality).'),
  ('ap-topic-micro-supply_q1', 'ap-topic-micro-supply', 1, false, 'C', 'Microeconomics', 'medium', 'If price elasticity of demand is 1.8, demand for the product is considered:', '["Inelastic","Unit Elastic","Elastic","Perfectly Inelastic"]'::jsonb, 'An elasticity value greater than 1 indicates price elastic demand.'),
  ('ap-topic-micro-supply_q2', 'ap-topic-micro-supply', 2, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'If the cross-price elasticity of demand between Good X and Good Y is $-1.5$, what is the economic relationship between the two goods?', '["They are complementary goods","They are substitute goods","They are inferior goods","They are luxury goods"]'::jsonb, 'A negative cross-price elasticity ($E_{xy} < 0$) indicates that an increase in the price of Good Y causes a decrease in quantity demanded of Good X, which defines complementary goods (e.g., coffee and coffee creamer).'),
  ('ap-topic-micro-supply_q3', 'ap-topic-micro-supply', 3, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'When the price of a product increases from $\$10$ to $\$12$, the quantity demanded decreases from 100 units to 80 units. Using the midpoint formula, what is the price elasticity of demand?', '["1.22 (elastic)","0.82 (inelastic)","1.00 (unit elastic)","2.00 (elastic)"]'::jsonb, 'Midpoint formula: $%\Delta Q = \frac{80 - 100}{(80 + 100)/2} = \frac{-20}{90} \approx -0.2222$. $%\Delta P = \frac{12 - 10}{(12 + 10)/2} = \frac{2}{11} \approx +0.1818$. Elasticity magnitude $|E_d| = \frac{0.2222}{0.1818} = \frac{20/90}{2/11} = \frac{2}{9} \times \frac{11}{2} = \frac{11}{9} \approx 1.22$. Since $|E_d| > 1$, demand is price elastic.'),
  ('ap-topic-micro-supply_q4', 'ap-topic-micro-supply', 4, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'According to the total revenue test, if a firm increases its price and total revenue rises, the demand for its product is:', '["Inelastic","Elastic","Unit elastic","Perfectively elastic"]'::jsonb, 'When demand is price inelastic ($|E_d| < 1$), the percentage decrease in quantity demanded is smaller than the percentage increase in price, causing total revenue ($P \times Q$) to rise.'),
  ('ap-topic-micro-supply_q5', 'ap-topic-micro-supply', 5, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'What is the market consequence of a government imposing a binding price ceiling below the equilibrium market price?', '["A persistent shortage where quantity demanded exceeds quantity supplied","A persistent surplus where quantity supplied exceeds quantity demanded","An increase in producer surplus and elimination of deadweight loss","A shift of the supply curve to the right"]'::jsonb, 'A ceiling below market equilibrium prevents price from rising to clear the market. At the lower legal price, consumers demand more ($Q_d$) while producers supply less ($Q_s$), causing an ongoing shortage and deadweight loss.'),
  ('ap-topic-micro-supply_q6', 'ap-topic-micro-supply', 6, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'A competitive market has linear supply and demand. If the government levies a $\$2$ per-unit excise tax on producers and demand is significantly more inelastic than supply, who bears the greater economic tax incidence?', '["Consumers bear the majority of the tax burden through higher retail prices","Producers bear the entire tax burden because the tax was levied on them","Consumers and producers split the tax burden exactly 50-50","The government absorbs the tax burden"]'::jsonb, 'Tax incidence depends on relative elasticities, not legal statutory obligation. The more inelastic party is less responsive to price changes and cannot easily substitute away, bearing the larger economic burden.'),
  ('ap-topic-micro-supply_q7', 'ap-topic-micro-supply', 7, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'What defines a public good in microeconomic theory?', '["It is both non-excludable and non-rival in consumption","It is provided exclusively by private for-profit monopolies","It is excludable and rival in consumption","It is subsidized by the government but subject to congestion tolls"]'::jsonb, 'Public goods (like national defense or lighthouses) are non-excludable (non-payers cannot be prevented from benefiting) and non-rival (one person''s consumption does not reduce availability for others), leading to market failure via the free-rider problem.'),
  ('ap-topic-micro-supply_q8', 'ap-topic-micro-supply', 8, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'A perfectly competitive profit-maximizing firm operates in the short run. At its current output where $MR = MC = \$15$, its Average Total Cost is $ATC = \$18$ and its Average Variable Cost is $AVC = \$12$. What decision should the firm make in the short run?', '["Continue producing in the short run despite economic losses because price covers average variable cost ($P > AVC$)","Shut down operations immediately because it is earning economic losses ($P < ATC$)","Raise its market price to $\\$20$ to restore profits","Increase output until $ATC$ reaches $\\$15$"]'::jsonb, 'Because $P = \$15 > AVC = \$12$, the firm covers all variable costs and contributes $\$3$ per unit toward paying down fixed costs. Shutting down would force the firm to lose all fixed costs, so continuing production minimizes losses.'),
  ('ap-topic-micro-supply_q9', 'ap-topic-micro-supply', 9, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'Why does a single-price unregulated monopoly produce an inefficient output level compared to a perfectly competitive market?', '["The monopolist restricts output where $MR = MC$, producing where $P > MC$, creating deadweight loss","The monopolist produces where $P = MC$, driving consumer surplus to zero","The monopolist charges a price below its marginal cost","The monopolist generates a positive consumption externality"]'::jsonb, 'To sell an additional unit, a single-price monopoly must lower price on all units sold, so $MR < P$. It maximizes profit at $MR = MC$, resulting in price $P > MC$ (allocative inefficiency) and deadweight loss.'),
  ('ap-topic-micro-supply_q10', 'ap-topic-micro-supply', 10, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'When the production of a chemical fertilizer generates toxic runoff that pollutes downstream fisheries (a negative externality), what is the relationship between Marginal Private Cost ($MPC$) and Marginal Social Cost ($MSC$)?', '["$MSC > MPC$; unregulated market output exceeds the socially optimal output","$MSC < MPC$; unregulated market output is less than socially optimal","$MSC = MPC$; the market achieves allocative efficiency automatically","Social costs are zero because externalities are private matters"]'::jsonb, 'A negative externality imposes spillover costs on third parties: $MSC = MPC + \text{Marginal External Cost}$. Unregulated competitive markets consider only $MPC$, overproducing relative to the socially optimal quantity.'),
  ('ap-topic-micro-supply_q11', 'ap-topic-micro-supply', 11, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'In game theory, what defines a Nash equilibrium in a simultaneous two-player payoff matrix?', '["A combination of strategies where neither player has an incentive to unilaterally deviate given the other player''s strategy","A strategy that guarantees both players receive the maximum possible total payout","A situation where one player wins and the other player earns zero","A game with no dominant strategies"]'::jsonb, 'A Nash equilibrium is a state where each player chooses their best strategy given the strategy chosen by the other player, meaning no player can increase their payoff by unilaterally changing strategy.'),
  ('ap-topic-micro-supply_q12', 'ap-topic-micro-supply', 12, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'What does the Law of Diminishing Marginal Returns state about short-run production?', '["As successive units of a variable input (labor) are added to fixed inputs (capital), the additional output produced by each extra unit eventually declines","Total output declines immediately when the first worker is hired","Long-run average total cost always increases as factory size expands","Hiring more workers causes prices to fall automatically"]'::jsonb, 'In the short run, capital and plant size are fixed. Adding additional workers initially boosts productivity, but workers eventually crowd equipment, causing marginal product ($MP$) to diminish.'),
  ('ap-topic-micro-supply_q13', 'ap-topic-micro-supply', 13, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'If a consumer''s income increases by $10\%$ and the quantity demanded of instant ramen noodles decreases by $15\%$, what is the income elasticity of demand and how is the good classified?', '["Income elasticity is -1.5; instant ramen is an inferior good","Income elasticity is +1.5; instant ramen is a luxury good","Income elasticity is -0.67; instant ramen is a normal good","Income elasticity is +0.67; instant ramen is a necessity"]'::jsonb, 'Income elasticity $E_I = \frac{\%\Delta Q_d}{\%\Delta I} = \frac{-15\%}{+10\%} = -1.5$. A negative income elasticity designates an inferior good (consumption falls as income rises).'),
  ('ap-topic-micro-supply_q14', 'ap-topic-micro-supply', 14, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'What is the long-run equilibrium condition for a monopolistically competitive firm?', '["$P = ATC$ at an output level below minimum efficient scale, earning zero economic profit with excess capacity","$P = MC$, achieving full allocative and productive efficiency","Earning positive economic profit protected by insurmountable legal barriers to entry","Shutting down permanently because price is below average variable cost"]'::jsonb, 'Low entry barriers allow new firms to enter whenever short-run profits exist, shifting incumbent demand leftward until $P = ATC$ tangent (zero economic profit). Because the demand curve slopes downward, tangency occurs to the left of minimum $ATC$, resulting in excess capacity.'),
  ('ap-topic-micro-supply_q15', 'ap-topic-micro-supply', 15, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'Where does the Marginal Cost ($MC$) curve intersect the Average Total Cost ($ATC$) curve and Average Variable Cost ($AVC$) curve?', '["At their respective minimum points","At their respective vertical axis intercepts","At the point of inflection of the total revenue curve","At the shutdown price point exclusively"]'::jsonb, 'Whenever marginal cost is below average cost ($MC < ATC$), it pulls average cost down. When $MC > ATC$, it pulls average cost up. Therefore, $MC$ must pass through the exact minimum points of both $ATC$ and $AVC$.'),
  ('ap-topic-micro-supply_q16', 'ap-topic-micro-supply', 16, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'How does perfect price discrimination (first-degree price discrimination) affect consumer surplus and deadweight loss?', '["Consumer surplus is reduced to zero, all surplus is captured by the monopolist as profit, and deadweight loss is eliminated","Consumer surplus is maximized, and monopolist profits are zero","Deadweight loss reaches its maximum possible level","Total surplus drops to zero"]'::jsonb, 'A perfect price discriminator charges each consumer their exact willingness to pay. The firm produces up to $P = MC$ (allocatively efficient quantity), eliminating deadweight loss, but converts 100% of consumer surplus into producer surplus.'),
  ('ap-topic-micro-supply_q17', 'ap-topic-micro-supply', 17, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'In a competitive factor (labor) market, how many workers will a profit-maximizing firm hire?', '["Up to the point where the Marginal Revenue Product of Labor equals the Wage ($MRPL = W$)","Where total product of labor is maximized","Where average revenue product equals total variable cost","Where marginal physical product is zero"]'::jsonb, 'A firm in a competitive labor market hires workers until the additional revenue generated by the last worker ($MRPL = MP_L \times P$) equals the marginal resource cost (the market wage $W$).'),
  ('ap-topic-micro-supply_q18', 'ap-topic-micro-supply', 18, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'Which of the following causes an outward shift of the demand curve for coffee rather than a movement along the demand curve?', '["A medical study published proving that drinking coffee improves longevity and focus","A drop in the market price of coffee beans","A technological breakthrough reducing coffee roasting costs","An increase in sales taxes imposed on coffee retail shops"]'::jsonb, 'A change in the good''s own price causes movement along the curve. An external factor (favorable change in consumer tastes and preferences) shifts the entire demand curve outward to the right.'),
  ('ap-topic-micro-supply_q19', 'ap-topic-micro-supply', 19, false, 'A', 'Supply, Demand & Elasticity', 'medium', 'Consumer surplus is graphically represented as the area:', '["Below the demand curve and above the market price, out to the quantity purchased","Below the market price and above the supply curve","Between the average total cost curve and marginal cost curve","Enclosed by the deadweight loss triangle"]'::jsonb, 'Consumer surplus measures the net benefit to consumers: the area under the demand curve (willingness to pay) and above the price line (amount actually paid) across all units purchased.'),
  ('ap-topic-micro-supply_q20', 'ap-topic-micro-supply', 20, false, 'A', 'Supply, Demand & Elasticity', 'hard', 'When a firm doubles all its inputs and its total output increases by $150\%$, the firm is experiencing:', '["Economies of scale (increasing returns to scale)","Diseconomies of scale","Constant returns to scale","Diminishing marginal returns"]'::jsonb, 'If output increases by a greater percentage ($150\%$) than inputs ($100\%$ increase), long-run average total cost declines, which defines economies of scale (increasing returns to scale).')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-psych-cog_q1', 'ap-topic-psych-cog', 1, false, 'B', 'Psychology', 'easy', 'Which brain structure acts as the primary relay station for sensory information?', '["Hippocampus","Thalamus","Amygdala","Cerebellum"]'::jsonb, 'The thalamus routes sensory inputs to appropriate cortical areas.'),
  ('ap-topic-psych-cog_q2', 'ap-topic-psych-cog', 2, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'During the transmission of a neural impulse (action potential), which ion channels open first along the axon membrane, causing rapid depolarization?', '["Voltage-gated sodium ($Na^+$) channels, allowing $Na^+$ ions to rush into the neuron","Potassium ($K^+$) channels, allowing $K^+$ ions to exit the neuron","Chloride ($Cl^-$) channels, causing hyperpolarization","Calcium ($Ca^{2+}$) pumps pushing calcium out of synaptic vesicles"]'::jsonb, 'When the axon hillock reaches threshold ($-55\text{ mV}$), voltage-gated sodium channels open rapidly, allowing positive $Na^+$ ions to flood into the intracellular fluid, depolarizing the membrane toward $+30\text{ mV}$.'),
  ('ap-topic-psych-cog_q3', 'ap-topic-psych-cog', 3, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'A patient suffers brain trauma and subsequently loses the ability to form new explicit long-term episodic memories (anterograde amnesia), although older childhood memories remain intact. Which brain structure was most likely damaged?', '["Hippocampus","Amygdala","Cerebellum","Medulla oblongata"]'::jsonb, 'The hippocampus is essential for consolidating new explicit (declarative/episodic) memories from short-term to long-term storage (famously demonstrated in patient H.M.).'),
  ('ap-topic-psych-cog_q4', 'ap-topic-psych-cog', 4, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'Which neurotransmitter plays a crucial role in motor control, reward reinforcement, and executive function, and whose depletion is the hallmark of Parkinson''s disease?', '["Dopamine","Serotonin","GABA","Acetylcholine"]'::jsonb, 'Dopamine pathways from the substantia nigra to the basal ganglia regulate voluntary motor control. Degeneration of these dopamine-producing neurons causes Parkinson''s motor deficits.'),
  ('ap-topic-psych-cog_q5', 'ap-topic-psych-cog', 5, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'According to Weber''s Law in psychophysics, the just noticeable difference ($JND$) between two sensory stimuli is:', '["A constant proportion of the initial stimulus intensity, rather than a constant numerical amount","An absolute fixed physical value for all human observers","Dependent entirely on whether the observer is asleep or awake","Inversely proportional to the square root of frequency"]'::jsonb, 'Weber''s Law states that $\frac{\Delta I}{I} = k$: the threshold for detecting a difference between two stimuli is a constant percentage ratio of the original stimulus magnitude.'),
  ('ap-topic-psych-cog_q6', 'ap-topic-psych-cog', 6, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'Which Gestalt principle describes the visual perceptual tendency to organize elements that move together in the same direction and speed into a single unified figure?', '["Common fate","Proximity","Closure","Simplicity (Pragnanz)"]'::jsonb, 'The Gestalt law of common fate states that visual elements moving in the same direction and velocity (such as a flock of birds or school of fish) are perceived as a single coherent group.'),
  ('ap-topic-psych-cog_q7', 'ap-topic-psych-cog', 7, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'In Ivan Pavlov''s classical conditioning experiments with dogs, what was the meat powder and what was the salivation in response to the bell?', '["Meat powder was the Unconditioned Stimulus (UCS); salivation to the bell was the Conditioned Response (CR)","Meat powder was the Conditioned Stimulus (CS); salivation to the bell was the Unconditioned Response (UCR)","Meat powder was the Conditioned Response (CR); bell was the Operant Stimulus","Meat powder was the Neutral Stimulus (NS); salivation was Extinction"]'::jsonb, 'Meat powder naturally triggers salivation without learning (UCS). Pairing the neutral bell with meat powder transforms the bell into a Conditioned Stimulus (CS), making salivation to the bell alone a Conditioned Response (CR).'),
  ('ap-topic-psych-cog_q8', 'ap-topic-psych-cog', 8, false, 'A', 'Brain, Sensation & Cognition', 'hard', 'A gambler plays a slot machine that pays out an unpredictable jackpot after an unpredictable number of lever pulls. What schedule of operant reinforcement is this?', '["Variable-ratio schedule","Fixed-ratio schedule","Variable-interval schedule","Fixed-interval schedule"]'::jsonb, 'Variable-ratio schedules deliver reinforcement after an unpredictable number of behavioral responses, producing very high, steady response rates highly resistant to extinction.'),
  ('ap-topic-psych-cog_q9', 'ap-topic-psych-cog', 9, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'A student memorizes a new phone number. When trying to recall their old phone number the next day, they can only remember the new one. What memory phenomenon does this represent?', '["Retroactive interference","Proactive interference","Anterograde amnesia","Source monitoring error"]'::jsonb, 'Retroactive interference occurs when newly acquired information disrupts the retrieval of previously stored information. (Proactive interference is the reverse, where old memories block new learning).'),
  ('ap-topic-psych-cog_q10', 'ap-topic-psych-cog', 10, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'What is the "availability heuristic" in cognitive decision-making?', '["Estimating the probability or frequency of an event based on how easily examples immediately come to mind from memory","Judging how likely an event is based on how closely it matches a mental prototype","Continuing an endeavor once an investment in money, effort, or time has been made","Searching exclusively for evidence that confirms one''s pre-existing beliefs"]'::jsonb, 'The availability heuristic leads individuals to judge the likelihood of events by the ease with which relevant instances are retrieved from memory (e.g., overestimating plane crash risk after viewing news reports).'),
  ('ap-topic-psych-cog_q11', 'ap-topic-psych-cog', 11, false, 'A', 'Brain, Sensation & Cognition', 'hard', 'During which stage of sleep do dreams primarily occur, characterized by rapid eye movements, low-amplitude desynchronized EEG waves, and muscular atonia (sleep paralysis)?', '["REM sleep","NREM Stage 3 (deep slow-wave sleep)","NREM Stage 1","NREM Stage 2"]'::jsonb, 'REM (Rapid Eye Movement) sleep is paradoxical: brain activity resembles alert wakefulness (low-voltage beta/theta waves), autonomic arousal increases, vivid dreaming occurs, and skeletal muscle tone is inhibited to prevent dream enactment.'),
  ('ap-topic-psych-cog_q12', 'ap-topic-psych-cog', 12, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'Which photoreceptors in the human retina are highly concentrated in the fovea and are specialized for color vision and high visual acuity in bright illumination?', '["Cones","Rods","Ganglion cells","Bipolar cells"]'::jsonb, 'Cones provide high-resolution sharp central vision and color perception in bright light, densely concentrated in the fovea centralis. Rods populate the peripheral retina and mediate monochromatic dim-light vision.'),
  ('ap-topic-psych-cog_q13', 'ap-topic-psych-cog', 13, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'What is the fundamental difference between negative reinforcement and positive punishment in operant conditioning?', '["Negative reinforcement removes an aversive stimulus to increase a behavior; positive punishment adds an aversive stimulus to decrease a behavior","Negative reinforcement decreases a behavior; positive punishment increases a behavior","Both processes seek to eliminate undesirable behaviors permanently","Negative reinforcement involves physical pain, while positive punishment involves praise"]'::jsonb, 'All reinforcement *increases* target behavior: negative reinforcement removes an unpleasant condition (e.g., fastening seatbelt to stop buzzing). Punishment *decreases* target behavior: positive punishment administers an aversive stimulus (e.g., a speeding ticket).'),
  ('ap-topic-psych-cog_q14', 'ap-topic-psych-cog', 14, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'George A. Miller''s classic 1956 research established that the capacity limit of human short-term (working) memory for unchunked items is approximately:', '["$7 \\pm 2$ items","$12 \\pm 2$ items","$3 \\pm 1$ items","Unlimited capacity"]'::jsonb, 'Miller showed that human working memory can hold approximately 7 bits (plus or minus 2) of meaningful information simultaneously without active rehearsal or organizational chunking.'),
  ('ap-topic-psych-cog_q15', 'ap-topic-psych-cog', 15, false, 'A', 'Brain, Sensation & Cognition', 'hard', 'A split-brain patient with a severed corpus callosum fixates on a central screen. A picture of a spoon is briefly flashed to the patient''s left visual field. How can the patient report what they saw?', '["They cannot verbally name the spoon, but they can pick it out from a group of objects with their left hand","They can immediately say \"spoon\" aloud, but cannot touch it","They can write the word \"spoon\" using their right hand","They experience total visual blindness in both eyes"]'::jsonb, 'Images in the left visual field project to the right visual cortex. The right hemisphere controls the left hand but lacks Broca''s speech production center (located in the left hemisphere). Without the corpus callosum, the patient cannot name the object verbally, but can tactilely identify it with the left hand.'),
  ('ap-topic-psych-cog_q16', 'ap-topic-psych-cog', 16, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'Which cognitive bias causes people to search for, interpret, and recall information in a way that confirms their pre-existing hypotheses while ignoring contradictory evidence?', '["Confirmation bias","Hindsight bias","Framing effect","Functional fixedness"]'::jsonb, 'Confirmation bias is the tendency to gather or interpret information selectively to corroborate prior beliefs, disregarding contrary data.'),
  ('ap-topic-psych-cog_q17', 'ap-topic-psych-cog', 17, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'According to the opponent-process theory of color vision, which color pairings operate in antagonistic physiological channels?', '["Red vs Green, Blue vs Yellow, Black vs White","Red vs Blue, Green vs Yellow","Red vs Violet, Green vs Orange","Blue vs Green, Red vs White"]'::jsonb, 'Ewald Hering''s opponent-process theory explains negative afterimages via receptor channels operating in opposing pairs: red-green, blue-yellow, and black-white.'),
  ('ap-topic-psych-cog_q18', 'ap-topic-psych-cog', 18, false, 'A', 'Brain, Sensation & Cognition', 'hard', 'How does Noam Chomsky''s nativist theory of language acquisition differ from B.F. Skinner''s behaviorist theory?', '["Chomsky proposed that humans are born with an innate Language Acquisition Device (LAD) and universal grammar, whereas Skinner argued language is acquired through operant conditioning and imitation","Chomsky argued language is learned strictly through parental reinforcement","Skinner believed humans have a biological module for grammar in the cerebellum","Chomsky claimed infants cannot comprehend language until adolescence"]'::jsonb, 'Chomsky highlighted the "poverty of the stimulus," arguing that children generate novel grammatical sentences without direct training due to an innate, biologically prewired Language Acquisition Device (LAD), rejecting Skinner''s purely environmental reinforcement model.'),
  ('ap-topic-psych-cog_q19', 'ap-topic-psych-cog', 19, false, 'A', 'Brain, Sensation & Cognition', 'medium', 'What is "functional fixedness" in problem solving?', '["The cognitive tendency to view an object only in terms of its customary, traditional function, hindering creative problem resolution","The ability to quickly adapt tools to multiple novel uses","A permanent neurological deficit preventing tool manipulation","The cognitive preference for algorithms over heuristics"]'::jsonb, 'Functional fixedness is a mental block against using an object in a novel way that is required to solve a problem (e.g., failing to realize a coin can be used as a screwdriver).'),
  ('ap-topic-psych-cog_q20', 'ap-topic-psych-cog', 20, false, 'A', 'Brain, Sensation & Cognition', 'hard', 'Which brain region acts as the sensory relay station routing incoming sensory signals (except olfaction) to corresponding cerebral cortex sensory processing centers?', '["Thalamus","Hypothalamus","Pons","Basal ganglia"]'::jsonb, 'The thalamus receives visual, auditory, gustatory, and somatosensory inputs and relays them to appropriate cortical regions (occipital, temporal, parietal lobes). Olfactory signals bypass the thalamus, routing directly to the olfactory bulb.'),
  ('ap-topic-usgov-const_q1', 'ap-topic-usgov-const', 1, false, 'A', 'US Government', 'easy', 'Which Federalist paper argued that a large republic is the best defense against factions?', '["Federalist No. 10","Federalist No. 51","Federalist No. 70","Federalist No. 78"]'::jsonb, 'James Madison authored Federalist No. 10 addressing faction control.'),
  ('ap-topic-usgov-const_q2', 'ap-topic-usgov-const', 2, false, 'A', 'Constitutional Foundations', 'medium', 'In *Federalist No. 10*, James Madison argued that the most effective remedy for controlling the dangerous effects of faction is:', '["Establishing a large, extended commercial republic where diverse competing interests prevent any single faction from dominating","Outlawing political parties and interest groups by constitutional amendment","Eliminating liberty so factions cannot form","Giving all citizens identical opinions and passions"]'::jsonb, 'Madison argued that destroying liberty to eliminate factions is worse than the disease. In a large extended republic, the multiplicity of competing factions makes it difficult for any majority faction to coordinate and oppress minority rights.'),
  ('ap-topic-usgov-const_q3', 'ap-topic-usgov-const', 3, false, 'A', 'Constitutional Foundations', 'medium', 'What foundational constitutional mechanism is defended by James Madison in *Federalist No. 51* with the famous phrase "Ambition must be made to counteract ambition"?', '["Separation of powers and checks and balances among governmental branches","The direct popular election of federal judges","The complete elimination of the presidential veto","Unicameral congressional legislative supremacy"]'::jsonb, 'Madison argued in *Federalist No. 51* that human nature necessitates dividing power between distinct executive, legislative, and judicial branches, giving each branch constitutional means and personal motives to resist encroachments by the others.'),
  ('ap-topic-usgov-const_q4', 'ap-topic-usgov-const', 4, false, 'A', 'Constitutional Foundations', 'medium', 'What constitutional power allows Congress to enact legislation deemed necessary to carry out its explicitly enumerated powers (Article I, Section 8)?', '["The Necessary and Proper Clause (Elastic Clause)","The Ex Post Facto Clause","The Full Faith and Credit Clause","The Privileges and Immunities Clause"]'::jsonb, 'The Necessary and Proper Clause grants Congress implied powers to pass all laws appropriate and helpful to execute its enumerated responsibilities (confirmed in *McCulloch v. Maryland*).'),
  ('ap-topic-usgov-const_q5', 'ap-topic-usgov-const', 5, false, 'A', 'Constitutional Foundations', 'hard', 'In *McCulloch v. Maryland* (1819), the Supreme Court ruled that:', '["Congress possessed the implied constitutional power to charter a national bank, and states could not tax an instrument of the federal government","States could nullify federal bank branches within their sovereign territory","The Second Bank of the United States was unconstitutional because banking is an exclusive state power","The federal government had no authority to collect interstate tariffs"]'::jsonb, 'Marshall ruled that the Necessary and Proper Clause gave Congress implied power to create the Second Bank of the United States, and under the Supremacy Clause, "the power to tax involves the power to destroy," barring Maryland from taxing the bank.'),
  ('ap-topic-usgov-const_q6', 'ap-topic-usgov-const', 6, false, 'A', 'Constitutional Foundations', 'medium', 'How do block grants differ from categorical grants in federal intergovernmental transfers?', '["Block grants provide broad funds with significant state discretion, whereas categorical grants are targeted for specific narrow purposes with federal conditions","Block grants are strictly unconstitutional under the Tenth Amendment","Categorical grants give states total freedom to spend funds without federal oversight","Block grants require states to repay the funds with interest"]'::jsonb, 'Categorical grants are earmarked for specific programs (e.g., school lunches, highway medians) with strict mandates. Block grants combine categorical grants into broad policy areas (e.g., community development), giving states wide implementation flexibility.'),
  ('ap-topic-usgov-const_q7', 'ap-topic-usgov-const', 7, false, 'A', 'Constitutional Foundations', 'hard', 'In *United States v. Lopez* (1995), the Supreme Court limited federal power by ruling that:', '["The Gun-Free School Zones Act exceeded congressional authority under the Commerce Clause because carrying a gun in a local school zone was not an economic activity with substantial effect on interstate commerce","Congress possessed absolute power to regulate all local criminal activity under the Commerce Clause","Second Amendment rights applied only to members of state militias","States were barred from passing local gun safety ordinances"]'::jsonb, 'Chief Justice Rehnquist marked a resurgence of federalism limits, holding that possessing a gun in a school zone was a non-economic local activity without substantial nexus to interstate commerce, reining in expansive Commerce Clause interpretations.'),
  ('ap-topic-usgov-const_q8', 'ap-topic-usgov-const', 8, false, 'A', 'Constitutional Foundations', 'medium', 'What is the doctrine of "selective incorporation"?', '["The gradual, case-by-case application of fundamental Bill of Rights protections to state governments via the Fourteenth Amendment''s Due Process Clause","The automatic application of all ten amendments to state law at the moment the Bill of Rights was ratified in 1791","The constitutional process by which territories are incorporated as US states","The power of the Supreme Court to select which justices serve on circuit benches"]'::jsonb, 'Originally, the Bill of Rights constrained only the federal government (*Barron v. Baltimore*). Through selective incorporation beginning in 1925 (*Gitlow v. New York*), the Supreme Court applied individual guarantees to states using the 14th Amendment Due Process Clause.'),
  ('ap-topic-usgov-const_q9', 'ap-topic-usgov-const', 9, false, 'A', 'Constitutional Foundations', 'hard', 'In *Citizens United v. Federal Election Commission* (2010), the Supreme Court ruled that:', '["Independent political expenditures by corporations and labor unions are protected speech under the First Amendment and cannot be capped by federal law","Direct financial donations from corporations to candidate campaign accounts are fully legal and unlimited","All campaign advertising on television is unconstitutional","Congress can ban documentary films released within 60 days of an election"]'::jsonb, 'The 5-4 ruling held that political spending is protected First Amendment speech, striking down restrictions on independent political broadcast expenditures by corporations and unions, which catalyzed Super PAC proliferation.'),
  ('ap-topic-usgov-const_q10', 'ap-topic-usgov-const', 10, false, 'A', 'Constitutional Foundations', 'medium', 'What procedure allows the United States Senate to end a filibuster and bring a bill or nomination to a final floor vote?', '["A cloture motion invoking Rule XXII, requiring a three-fifths vote (60 senators)","A simple majority motion approved by the Vice President","A discharge petition signed by 218 senators","An executive proclamation issued by the President"]'::jsonb, 'Under Senate Rule XXII, invoking cloture terminates floor debate on legislation, requiring a three-fifths supermajority of all sworn senators (typically 60 votes).'),
  ('ap-topic-usgov-const_q11', 'ap-topic-usgov-const', 11, false, 'A', 'Constitutional Foundations', 'medium', 'Which of the following is an exclusive constitutional power granted solely to the House of Representatives?', '["Originating all revenue and tax bills (the Origination Clause)","Confirming federal judicial nominees and cabinet secretaries","Ratifying foreign treaties negotiated by the executive branch","Conducting trials on articles of impeachment"]'::jsonb, 'Article I, Section 7 mandates that all bills for raising revenue must originate in the House of Representatives, reflecting direct accountability to the electorate.'),
  ('ap-topic-usgov-const_q12', 'ap-topic-usgov-const', 12, false, 'A', 'Constitutional Foundations', 'medium', 'What is an "iron triangle" in public policymaking?', '["A mutually beneficial relationship among a congressional committee, an executive bureaucratic agency, and an interest group","The formal constitutional separation among the executive, legislative, and judicial branches","A trilateral trade agreement among three sovereign nations","The political alliance between the President, Vice President, and Speaker of the House"]'::jsonb, 'An iron triangle is an entrenched policy sub-government where interest groups provide campaign funds, congressional subcommittees appropriate funds, and bureaucratic agencies write favorable regulations for that industry.'),
  ('ap-topic-usgov-const_q13', 'ap-topic-usgov-const', 13, false, 'A', 'Constitutional Foundations', 'hard', 'In *Tinker v. Des Moines Independent Community School District* (1969), the Supreme Court affirmed that public school students:', '["Do not shed their constitutional rights to freedom of speech or expression at the schoolhouse gate, protecting silent symbolic protest","Have zero First Amendment rights while physically on school campus","Cannot be disciplined for any speech, even if it incites imminent physical violence","Can be required to recite mandatory religious prayers"]'::jsonb, 'The Court upheld students'' right to wear black armbands protesting the Vietnam War, ruling that schools cannot censor student expression unless it substantially disrupts school operations or invades others'' rights.'),
  ('ap-topic-usgov-const_q14', 'ap-topic-usgov-const', 14, false, 'A', 'Constitutional Foundations', 'medium', 'What is the function of a "discharge petition" in the United States House of Representatives?', '["To force a bill out of a reluctant committee onto the House floor for a vote, requiring signatures from an absolute majority (218 members)","To expel an unruly member of the House for ethical misconduct","To override a presidential pocket veto without debate","To automatically adjourn a congressional session"]'::jsonb, 'If a committee pigeonholes a bill, a discharge petition signed by 218 House members forces the bill directly onto the floor for debate and vote, circumventing committee chair resistance.'),
  ('ap-topic-usgov-const_q15', 'ap-topic-usgov-const', 15, false, 'A', 'Constitutional Foundations', 'hard', 'What core argument did Alexander Hamilton present in *Federalist No. 78* regarding the federal judiciary?', '["The judiciary is the \"least dangerous branch\" because it has neither the sword nor the purse, and life tenure ensures judicial independence from political branches","Judges should be elected every two years by the general public","The Supreme Court must be subordinated to the directives of the President","Federal courts should be stripped of the power of judicial review"]'::jsonb, 'In *Federalist No. 78*, Hamilton argued that the judiciary possesses neither force nor will, only judgment. Lifetime tenure insulated judges from executive pressure and legislative majoritarian passions.'),
  ('ap-topic-usgov-const_q16', 'ap-topic-usgov-const', 16, false, 'A', 'Constitutional Foundations', 'medium', 'How does the Tenth Amendment protect states'' rights under American constitutional federalism?', '["It reserves all powers not delegated to the federal government nor prohibited to the states to the states, or to the people (reserved powers)","It allows states to coin their own state currencies","It permits states to sign treaties with foreign monarchies","It gives state governors the power to veto federal Supreme Court rulings"]'::jsonb, 'The Tenth Amendment embodies the principle of reserved powers: any power not explicitly or implicitly granted to the national government by the Constitution remains with the states or the citizenry.'),
  ('ap-topic-usgov-const_q17', 'ap-topic-usgov-const', 17, false, 'A', 'Constitutional Foundations', 'hard', 'In *Baker v. Carr* (1962), what doctrine did the Supreme Court establish regarding state legislative redistricting?', '["Legislative apportionment is a justiciable constitutional issue under the Fourteenth Amendment''s Equal Protection Clause (\"one person, one vote\")","Apportionment is a purely non-justiciable political question that courts can never review","States are legally required to draw districts based exclusively on geographic land area rather than population","Federal courts cannot redraw congressional boundaries under any circumstances"]'::jsonb, '*Baker v. Carr* established that malapportioned legislative districts violate the Equal Protection Clause, enabling federal courts to review redistricting and establishing the "one person, one vote" standard in *Reynolds v. Sims*.'),
  ('ap-topic-usgov-const_q18', 'ap-topic-usgov-const', 18, false, 'A', 'Constitutional Foundations', 'medium', 'What is an informal power of the President of the United States that is not explicitly written in Article II of the Constitution?', '["Issuing executive orders and using the \"bully pulpit\" to shape public opinion","Serving as Commander in Chief of the armed forces","Granting reprieves and pardons for federal offenses","Appointing federal judges with the advice and consent of the Senate"]'::jsonb, 'Formal powers are enumerated in Article II (veto, appointments, pardons, Commander in Chief). Informal powers emerged through precedent: executive orders, executive agreements, signing statements, and the bully pulpit.'),
  ('ap-topic-usgov-const_q19', 'ap-topic-usgov-const', 19, false, 'A', 'Constitutional Foundations', 'hard', 'In *Brutus No. 1*, what was the primary warning voiced by the Antifederalist author regarding the proposed Constitution?', '["The immense power granted by the Necessary and Proper Clause and Supremacy Clause would annihilate state sovereignty and lead to tyranny over a vast territory","The Articles of Confederation gave too much power to the national congress","The executive branch lacked the authority to command a standing army","The judicial branch was too weak to enforce contracts"]'::jsonb, 'Brutus argued that a vast consolidated republic could not preserve liberty. The Supremacy and Elastic Clauses would allow the national government to absorb all state powers, creating an uncontrollable centralized aristocracy.'),
  ('ap-topic-usgov-const_q20', 'ap-topic-usgov-const', 20, false, 'A', 'Constitutional Foundations', 'medium', 'How does the First Amendment''s Establishment Clause differ from its Free Exercise Clause?', '["The Establishment Clause prohibits government from endorsing or establishing a state-sponsored religion; the Free Exercise Clause protects individuals'' rights to practice their chosen faith","The Establishment Clause allows mandatory school prayer; the Free Exercise Clause bans church attendance","The Establishment Clause applies only to federal agencies, while the Free Exercise Clause applies only to states","Both clauses are strictly identical in legal application"]'::jsonb, 'The First Amendment contains two complementary religion guarantees: the Establishment Clause erects a wall of separation barring government sponsorship of religion, while the Free Exercise Clause protects voluntary religious observance from governmental prohibition.'),
  ('ap-topic-compgov-sys_q1', 'ap-topic-compgov-sys', 1, false, 'C', 'Comparative Gov', 'medium', 'Which country in the AP Comparative Gov curriculum is classified as a federal republic?', '["United Kingdom","China","Nigeria","Iran"]'::jsonb, 'Nigeria is organized as a federal republic with multi-state government.'),
  ('ap-topic-compgov-sys_q2', 'ap-topic-compgov-sys', 2, false, 'A', 'Comparative Government', 'medium', 'What distinguishes an authoritarian regime from a democratic regime?', '["Authoritarian regimes limit political pluralism, suppress opposition parties, and undermine institutional checks on executive power","Authoritarian regimes have no constitutions","Democratic regimes never have political parties","Authoritarian regimes always have zero GDP growth"]'::jsonb, 'Authoritarian systems restrict civic participation, competitive elections, and civil liberties.'),
  ('ap-topic-compgov-sys_q3', 'ap-topic-compgov-sys', 3, false, 'A', 'Comparative Government', 'medium', 'What is a rentier state in comparative politics (e.g., Iran, Nigeria, Russia)?', '["A state that derives a significant portion of its national revenue from leasing natural resources (like oil/gas) to foreign clients","A state where citizens pay rent directly to the monarch","A nation with zero government debt","A state that operates without taxes"]'::jsonb, 'Rentier states rely heavily on oil/gas export revenues, reducing their dependence on domestic tax accountability.'),
  ('ap-topic-compgov-sys_q4', 'ap-topic-compgov-sys', 4, false, 'A', 'Comparative Government', 'medium', 'What electoral system is used in the United Kingdom for electing Members of Parliament (House of Commons)?', '["Single-Member District First-Past-The-Post (FPTP) plurality voting","Proportional Representation with party lists","Ranked-choice alternative vote","Two-round majoritarian runoff"]'::jsonb, 'The UK uses FPTP: the candidate with the most votes in each single-member constituency wins the seat.'),
  ('ap-topic-compgov-sys_q5', 'ap-topic-compgov-sys', 5, false, 'A', 'Comparative Government', 'medium', 'How does the Islamic Republic of Iran integrate theocracy and democracy in its governmental structure?', '["A Supreme Leader and Guardian Council exercise religious veto authority over an elected President and Majlis (Parliament)","Complete separation of mosque and state","The President holds absolute unilateral power without religious oversight","Direct democracy through annual public referendums"]'::jsonb, 'Iran''s constitution subordinates elected democratic bodies (Majlis, Presidency) to unelected clerical oversight (Supreme Leader, Guardian Council).'),
  ('ap-topic-compgov-sys_q6', 'ap-topic-compgov-sys', 6, false, 'A', 'Comparative Government', 'medium', 'What political development characterized Mexico''s transition in the late 1990s and 2000?', '["The end of 71-year single-party dominance by the PRI with the democratic election of Vicente Fox (PAN)","The establishment of a military dictatorship","The dissolution of the Supreme Court","The abolition of the presidency"]'::jsonb, 'The 2000 election of Vicente Fox marked Mexico''s transition to multiparty competitive electoral democracy.'),
  ('ap-topic-compgov-sys_q7', 'ap-topic-compgov-sys', 7, false, 'A', 'Comparative Government', 'medium', 'What role does the National People''s Congress (NPC) play in the political system of the People''s Republic of China?', '["It is the constitutionally highest organ of state power, but in practice acts as a formal legislative body executing Chinese Communist Party (CCP) directives","It is an independent opposition legislature","It chooses the prime minister via secret ballot","It oversees the private judicial bar"]'::jsonb, 'The NPC provides formal institutional legitimacy while remaining subordinate to CCP party leadership.'),
  ('ap-topic-compgov-sys_q8', 'ap-topic-compgov-sys', 8, false, 'A', 'Comparative Government', 'medium', 'What is prebendalism in Nigerian politics?', '["The practice of politicians using government offices to channel state revenues and patronage to their own ethnic and religious client groups","A system of proportional taxation","The federal separation of oil refineries","A judicial term limits law"]'::jsonb, 'Prebendalism describes pervasive clientelist patronage networks where state resources are treated as personal or ethnic spoils.'),
  ('ap-topic-compgov-sys_q9', 'ap-topic-compgov-sys', 9, false, 'A', 'Political Systems & Regimes', 'medium', 'What is the fundamental constitutional difference between a parliamentary system and a presidential system of government?', '["In a parliamentary system, the executive (prime minister) is chosen from and accountable to the legislature, whereas in a presidential system, the president is separately elected with independent constitutional powers","In a parliamentary system, there is no legislative branch","In a presidential system, the head of state and head of government are always two separate individuals","Parliamentary systems never have national political parties"]'::jsonb, 'Parliamentary systems feature fused legislative and executive powers: the prime minister is selected from the parliamentary majority. Presidential systems feature separation of powers with distinct mandates and fixed terms.'),
  ('ap-topic-compgov-sys_q10', 'ap-topic-compgov-sys', 10, false, 'A', 'Political Systems & Regimes', 'hard', 'What defines an "illiberal democracy" (hybrid regime) in comparative politics?', '["A political system with competitive elections that nonetheless lacks rule of law, civil liberties, judicial independence, and an open media environment","A totalitarian state with zero elections or parliaments","A direct democracy where citizens vote directly on every municipal statute","A constitutional monarchy with a symbolic monarch and robust civil liberties"]'::jsonb, 'An illiberal democracy maintains the procedural trappings of elections, but lacks the liberal institutions essential for substantive democracy: fair ballot access, press freedom, judicial independence, and minority protections.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-compgov-sys_q11', 'ap-topic-compgov-sys', 11, false, 'A', 'Political Systems & Regimes', 'medium', 'According to Duverger''s Law in political science, what type of party system is favored by single-member district plurality (first-past-the-post) electoral systems?', '["A stable two-party system","A fragmented multi-party coalition system","A permanent single-party dictatorship","A system with no organized political parties"]'::jsonb, 'Maurice Duverger demonstrated that single-member plurality elections incentivize tactical voting and coalition building, naturally filtering competitors into a two-party system. Proportional representation systems foster multi-party systems.'),
  ('ap-topic-compgov-sys_q12', 'ap-topic-compgov-sys', 12, false, 'A', 'Political Systems & Regimes', 'medium', 'What is political legitimacy in comparative government?', '["The widespread public acceptance and recognition of a government''s right to rule and exercise authority","The total number of police officers employed by the interior ministry","The monetary wealth possessed by the head of state","The signing of bilateral trade agreements with the United Nations"]'::jsonb, 'Legitimacy is the citizen belief that a governing regime has the rightful authority to formulate and enforce binding laws, derived from tradition, charismatic appeal, or rational-legal constitutional processes (Max Weber).'),
  ('ap-topic-compgov-sys_q13', 'ap-topic-compgov-sys', 13, false, 'A', 'Political Systems & Regimes', 'hard', 'What distinguishes a unitary state from a federal state?', '["In a unitary state, ultimate sovereign authority is concentrated exclusively in the national central government, whereas in a federal state, sovereignty is constitutionally shared with subnational governments","Unitary states never have regional municipal courts","Federal states are always governed by a hereditary monarch","Unitary states cannot enter into international treaties"]'::jsonb, 'In a unitary system (e.g., the UK, China), subnational bodies exercise only powers devolved to them by the central government. In a federal system (e.g., the US, Mexico, Nigeria), subnational powers are constitutionally protected.'),
  ('ap-topic-compgov-sys_q14', 'ap-topic-compgov-sys', 14, false, 'A', 'Political Systems & Regimes', 'medium', 'How does a vibrant, autonomous civil society strengthen democratic consolidation?', '["By providing independent associations, unions, and advocacy groups that hold the state accountable and organize citizen participation outside government control","By replacing the national military with private militias","By eliminating the need for periodic parliamentary elections","By giving the ruling party control over all newspapers"]'::jsonb, 'Civil society consists of voluntary non-governmental groups (trade unions, religious organizations, NGOs). A robust civil society provides independent checks on executive power, builds social capital, and articulates public interests.'),
  ('ap-topic-compgov-sys_q15', 'ap-topic-compgov-sys', 15, false, 'A', 'Political Systems & Regimes', 'hard', 'What is a "rentier state" in comparative politics?', '["A state that derives the substantial portion of its national revenue from renting or leasing natural resource endowments (such as oil or gas) to foreign actors rather than taxation","A country where all residential housing is owned by private landlords","A government that borrows all annual expenditure from the World Bank","A regime with zero natural resources that relies entirely on agricultural barter"]'::jsonb, 'A rentier state (e.g., Iran, Russia, Nigeria) generates massive external resource rents (oil/gas). Because the regime does not rely on domestic citizen taxation, it has reduced accountability to the public ("no representation without taxation").'),
  ('ap-topic-compgov-sys_q16', 'ap-topic-compgov-sys', 16, false, 'A', 'Political Systems & Regimes', 'medium', 'What distinguishes a "head of state" from a "head of government" in comparative systems?', '["The head of state serves as the symbolic representative of the nation''s unity, while the head of government directs the daily administrative and executive business of governing","The head of state writes all judicial opinions, while the head of government commands the navy","Both roles must always be filled by the exact same political figure","The head of government is appointed for life, while the head of state faces annual elections"]'::jsonb, 'In many systems (e.g., the UK with the Monarch and Prime Minister), the head of state embodies national continuity and diplomatic ceremony, while the head of government oversees the cabinet, policy execution, and legislative agenda.'),
  ('ap-topic-compgov-sys_q17', 'ap-topic-compgov-sys', 17, false, 'A', 'Political Systems & Regimes', 'medium', 'What electoral mechanism in proportional representation (PR) systems allows parties to gain parliamentary seats?', '["Parties receive seats roughly proportional to their share of the popular vote, provided they surpass a statutory threshold","The single candidate with the most votes in each district wins 100% of the representation","Seats are awarded to the party that spends the most money on campaign advertising","The head of state selects delegates based on family lineage"]'::jsonb, 'In proportional representation systems, multimember districts allocate legislative seats in direct proportion to the percentage of votes earned by each party list, facilitating multi-party representation.'),
  ('ap-topic-compgov-sys_q18', 'ap-topic-compgov-sys', 18, false, 'A', 'Political Systems & Regimes', 'hard', 'What is corporatism (state corporatism) in comparative authoritarian and hybrid regimes?', '["A system where the state sanctions and controls a limited number of recognized peak interest associations, co-opting labor and business into policy implementation while banning independent unions","Complete free-market deregulation where private corporations write all laws","A political system where corporate executives hold all cabinet seats","A socialist regime where private property is fully outlawed"]'::jsonb, 'In state corporatism, the government grants single monopolistic representation to officially licensed associations (e.g., one state-controlled labor federation), neutralizing grassroots political opposition by controlling interest group articulation.'),
  ('ap-topic-compgov-sys_q19', 'ap-topic-compgov-sys', 19, false, 'A', 'Political Systems & Regimes', 'medium', 'How does a vote of no confidence function in a parliamentary democracy?', '["If a majority of parliament votes that they lack confidence in the prime minister, the cabinet must resign or early general elections are called","The Supreme Court votes to remove the monarch for treason","Citizens petition to impeach all judges simultaneously","A municipal council dissolves the national parliament"]'::jsonb, 'Because executive power in a parliament depends on maintaining the confidence of the legislative majority, a successful vote of no confidence brings down the government, triggering either a new coalition or fresh national elections.'),
  ('ap-topic-compgov-sys_q20', 'ap-topic-compgov-sys', 20, false, 'A', 'Political Systems & Regimes', 'hard', 'What characterizes a totalitarian regime compared to an authoritarian regime?', '["Totalitarian regimes seek total ideological control over all public and private life, utilizing systematic terror, mass surveillance, and compulsory state youth mobilization","Totalitarian regimes allow an independent free press and multi-party elections","Authoritarian regimes exercise more intense control over daily family life than totalitarian regimes","Totalitarian regimes have zero police forces"]'::jsonb, 'Authoritarian regimes demand political obedience and monopoly of power, but often permit apolitical private life and religious practice. Totalitarian regimes (e.g., Nazi Germany, Stalinist USSR) aim for complete ideological reconstruction of society and total subjugation of the private sphere.'),
  ('ap-topic-humgeo-pop_q1', 'ap-topic-humgeo-pop', 1, false, 'A', 'Demographics', 'medium', 'In the Demographic Transition Model, Stage 2 is characterized by:', '["High birth rate and rapid decline in death rate","Low birth and death rates","High death rate and low birth rate","Declining birth rate and rising death rate"]'::jsonb, 'Stage 2 experiences rapid population growth due to declining death rates.'),
  ('ap-topic-humgeo-pop_q2', 'ap-topic-humgeo-pop', 2, false, 'A', 'Demographics', 'medium', 'What occurs during Stage 2 of the Demographic Transition Model (DTM)?', '["Death rates plummet rapidly due to medical/sanitation improvements while birth rates remain high, causing high natural increase (NIR)","Both birth and death rates remain high and fluctuating","Birth rates drop below death rates causing population decline","Zero population growth is achieved"]'::jsonb, 'Stage 2 features rapid mortality reduction (Industrial/Medical Revolution) while cultural fertility remains elevated, causing a population explosion.'),
  ('ap-topic-humgeo-pop_q3', 'ap-topic-humgeo-pop', 3, false, 'A', 'Demographics', 'medium', 'What was Thomas Malthus''s central thesis regarding population growth and food supply (1798)?', '["Population grows geometrically ($1, 2, 4, 8...$) while food production grows arithmetically ($1, 2, 3, 4...$), inevitably leading to famine and crisis","Technology will always produce infinite food abundance","Populations naturally stabilize at zero growth","Urbanization decreases agricultural yield"]'::jsonb, 'Malthus warned that exponential population growth would outstrip linear agricultural expansion unless checked by mortality or restraint.'),
  ('ap-topic-humgeo-pop_q4', 'ap-topic-humgeo-pop', 4, false, 'A', 'Demographics', 'medium', 'What is the total fertility rate (TFR) required to achieve generational population replacement in developed countries?', '["Approximately 2.1 children per woman","1.5 children per woman","3.0 children per woman","4.2 children per woman"]'::jsonb, 'A TFR of 2.1 replaces the parents while compensating for infant and childhood mortality.'),
  ('ap-topic-humgeo-pop_q5', 'ap-topic-humgeo-pop', 5, false, 'A', 'Demographics', 'medium', 'What demographic phenomenon is indicated by an expansive, wide-based population pyramid?', '["A high proportion of young children and rapid future population growth (Stage 2/3 developing nations)","An aging population with declining birth rates","Zero population growth","A massive influx of elderly retirees"]'::jsonb, 'A wide triangular base represents high birth rates and a young demographic age structure.'),
  ('ap-topic-humgeo-pop_q6', 'ap-topic-humgeo-pop', 6, false, 'A', 'Demographics', 'medium', 'According to Ravenstein''s Laws of Migration, most international long-distance migrants are:', '["Young adult individuals seeking economic opportunity","Entire multi-generational families with elderly members","Retirees moving for pleasant climate","Wealthy corporate executives only"]'::jsonb, 'Ravenstein observed that long-distance migrants are predominantly single young adults moving for employment.'),
  ('ap-topic-humgeo-pop_q7', 'ap-topic-humgeo-pop', 7, false, 'A', 'Demographics', 'medium', 'What is physiological population density?', '["The number of people per unit area of arable (farmable) land","The total population divided by total land area","The number of farmers per unit of arable land","The number of hospitals per city"]'::jsonb, 'Physiological density measures population pressure directly on available agricultural land resources.'),
  ('ap-topic-humgeo-pop_q8', 'ap-topic-humgeo-pop', 8, false, 'A', 'Demographics', 'medium', 'What is a push factor in human migration?', '["An adverse condition (e.g. war, famine, political persecution, natural disaster) that drives people to leave their origin country","A favorable job offer in a new city","A pleasant coastal retirement climate","Lower tax rates abroad"]'::jsonb, 'Push factors are negative circumstances that compel emigration from a homeland.'),
  ('ap-topic-humgeo-pop_q9', 'ap-topic-humgeo-pop', 9, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'In the Demographic Transition Model (DTM), what dynamic characterizes Stage 2?', '["Death rates plummet due to improvements in food supply and sanitation, while birth rates remain high, causing rapid natural increase","Both birth rates and death rates are high and fluctuating, resulting in low population growth","Birth rates drop sharply to match low death rates, stabilizing population growth","Birth rates drop below death rates, causing demographic decline"]'::jsonb, 'Stage 2 (associated with the Industrial/Medical Revolution) sees mortality rates collapse due to cleaner water, hygiene, and nutrition. High cultural birth rates persist, producing an explosion in natural population increase.'),
  ('ap-topic-humgeo-pop_q10', 'ap-topic-humgeo-pop', 10, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'What does a population pyramid with a very wide triangular base tapering rapidly to a sharp point indicate about a country''s demographic profile?', '["A high birth rate, high infant mortality, high youth dependency ratio, and rapid population expansion","A shrinking, aging population with low birth rates","An economically developed post-industrial country in Stage 5 of the DTM","A country where males significantly outnumber females at every age tier"]'::jsonb, 'A broad base represents high fertility rates (many young children), while steep tapering indicates high mortality across cohorts, characteristic of Stage 2 developing countries with high youth dependency burdens.'),
  ('ap-topic-humgeo-pop_q11', 'ap-topic-humgeo-pop', 11, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'According to Thomas Malthus''s 1798 essay on population, what disparity threatened human society?', '["Population grows exponentially (geometrically), whereas food production increases only arithmetically, inevitably leading to starvation and war","Urbanization would permanently reduce the fertility rate of rural farmers to zero","Industrial technology would produce excessive food surpluses causing economic deflation","Global cooling would prevent transatlantic wheat shipping"]'::jsonb, 'Malthus argued that human population grows geometrically ($1, 2, 4, 8, 16$), while food output increases arithmetically ($1, 2, 3, 4, 5$). Unchecked population inevitably outstrips carrying capacity, triggering Malthusian catastrophes.'),
  ('ap-topic-humgeo-pop_q12', 'ap-topic-humgeo-pop', 12, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'What is the "total fertility rate" (TFR) necessary to maintain a stable, replacement-level population in developed countries with low infant mortality?', '["Approximately 2.1 children per woman","Approximately 1.5 children per woman","Approximately 3.0 children per woman","Approximately 1.0 child per woman"]'::jsonb, 'Replacement-level fertility is approximately 2.1 births per woman: two children replace the parents, with an extra 0.1 compensating for infant/childhood mortality before reproductive age.'),
  ('ap-topic-humgeo-pop_q13', 'ap-topic-humgeo-pop', 13, false, 'A', 'Population Patterns & Demographic Transition', 'hard', 'How does physiological population density differ from arithmetic population density?', '["Physiological density measures total population per unit of arable (farmable) land, whereas arithmetic density measures total population per unit of total land area","Physiological density measures the number of doctors per thousand citizens","Arithmetic density measures urban population, while physiological density measures rural population","Physiological density counts only working-age adults"]'::jsonb, 'Arithmetic density is simply total people divided by total land area. Physiological density divides total population by arable land area, providing a more accurate measure of the agricultural pressure on food-producing ecosystems (e.g., Egypt).'),
  ('ap-topic-humgeo-pop_q14', 'ap-topic-humgeo-pop', 14, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'In Ernst Ravenstein''s Laws of Migration, which pattern accurately describes typical migration flows?', '["Most migrants travel short distances; long-distance migrants tend to head for major centers of commercial and industrial activity","Families with children migrate over longer international distances than young single adults","Urban residents are more migratory than rural agricultural workers","Migration flows generate zero counter-currents"]'::jsonb, 'Ravenstein observed that the majority of migrants move short distances (friction of distance). Long-distance migrants disproportionately choose major global urban destinations and are predominantly young single adults.'),
  ('ap-topic-humgeo-pop_q15', 'ap-topic-humgeo-pop', 15, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'Which of the following is an example of an economic "push factor" in voluntary human migration?', '["High local unemployment and a lack of job opportunities in one''s home region","High-paying manufacturing jobs available in a neighboring metropolitan area","Mild climate and abundant coastal recreational amenities","Democratic elections and religious tolerance in a foreign country"]'::jsonb, 'Push factors are negative conditions in a source region that compel individuals to leave (e.g., severe unemployment, poverty, crop failure). Pull factors are positive attractions drawing migrants into a destination.'),
  ('ap-topic-humgeo-pop_q16', 'ap-topic-humgeo-pop', 16, false, 'A', 'Population Patterns & Demographic Transition', 'hard', 'What demographic crisis faces countries entering Stage 5 of the Demographic Transition Model (such as Japan and Italy)?', '["Birth rates fall below death rates, leading to negative natural increase, a shrinking workforce, and an unsustainable elderly dependency ratio","Sudden spikes in infectious disease that collapse health services","Massive youth unemployment resulting from extreme fertility booms","Inability of local agriculture to produce sufficient calories"]'::jsonb, 'In Stage 5, TFR drops well below 2.1 (often 1.2-1.4). Death rates exceed birth rates, leading to natural population decline, severe shortages of entry-level labor, and strains on pension and healthcare systems.'),
  ('ap-topic-humgeo-pop_q17', 'ap-topic-humgeo-pop', 17, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'What is a "pronatalist" government policy designed to achieve?', '["To encourage higher birth rates through financial incentives, paid parental leave, and subsidized childcare","To restrict family sizes to one child per couple through government penalties","To encourage emigration of working-age adults to foreign nations","To promote sterilization and compulsory contraception"]'::jsonb, 'Pronatalist policies (used in France, Hungary, and Singapore) incentivize childbearing through tax credits, baby bonuses, and extended maternity/paternity benefits to counteract demographic aging.'),
  ('ap-topic-humgeo-pop_q18', 'ap-topic-humgeo-pop', 18, false, 'A', 'Population Patterns & Demographic Transition', 'hard', 'What phenomenon occurs when educated, highly skilled professionals emigrate in large numbers from developing nations to developed economies?', '["Brain drain","Chain migration","Remittance buffering","Transhumance"]'::jsonb, '"Brain drain" describes the international loss of human capital when physicians, engineers, scientists, and academics leave developing home nations seeking higher wages and better working environments abroad.'),
  ('ap-topic-humgeo-pop_q19', 'ap-topic-humgeo-pop', 19, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'According to the Epidemiologic Transition Model, what is the primary cause of mortality in Stage 3 and Stage 4 countries?', '["Chronic degenerative lifestyle illnesses (such as cardiovascular disease and cancer)","Pandemic bacterial infections like cholera and plague","Pestilence, infant malnutrition, and famine","Infections from contaminated municipal drinking water"]'::jsonb, 'Abdel Omran''s Epidemiologic Transition Model shows that as public health, antibiotics, and clean water eradicate infectious diseases (Stages 1-2), life expectancy rises, making chronic degenerative diseases (heart disease, cancer) primary mortality causes.'),
  ('ap-topic-humgeo-pop_q20', 'ap-topic-humgeo-pop', 20, false, 'A', 'Population Patterns & Demographic Transition', 'medium', 'What is the "ecumene" in human geography?', '["The permanently inhabited portion of the Earth''s surface","The region of the atmosphere where commercial airplanes fly","The designated boundary around a protected wildlife preserve","The agricultural zone devoted exclusively to cattle ranching"]'::jsonb, 'The ecumene refers to the portion of the Earth''s terrestrial surface settled by permanent human habitation, which has steadily expanded through agricultural and technological adaptations.'),
  ('ap-topic-afam-hist_q1', 'ap-topic-afam-hist', 1, false, 'B', 'African American Studies', 'medium', 'The Harlem Renaissance of the 1920s was primarily a flourishing of:', '["Industrial technology","African American literature, art, and music","Political party realignment","Agricultural expansion"]'::jsonb, 'Harlem was a vibrant hub for Black creative and intellectual expression.'),
  ('ap-topic-afam-hist_q2', 'ap-topic-afam-hist', 2, false, 'A', 'African American History', 'medium', 'What was the Middle Passage in the Transatlantic Slave Trade?', '["The horrific forced maritime voyage of enslaved Africans across the Atlantic Ocean to the Americas in crowded, disease-ridden slave ships","The overland caravan through the Sahara Desert","The Underground Railroad route to Canada","The migration of freedmen to northern cities"]'::jsonb, 'The Middle Passage was the brutal middle leg of the triangular trade where millions perished from disease, abuse, and starvation.'),
  ('ap-topic-afam-hist_q3', 'ap-topic-afam-hist', 3, false, 'A', 'African American History', 'medium', 'What was the significance of the Harlem Renaissance during the 1920s?', '["A flourishing cultural, literary, musical (Jazz), and intellectual movement centered in Harlem that celebrated Black identity and artistic expression","A series of political strikes against coal mines","The establishment of historically Black colleges in the South","A movement to repatriate all Black Americans to West Africa"]'::jsonb, 'Writers like Langston Hughes, Zora Neale Hurston, and artists like Duke Ellington revolutionized American art through Black cultural pride.'),
  ('ap-topic-afam-hist_q4', 'ap-topic-afam-hist', 4, false, 'A', 'African American History', 'medium', 'What did the Supreme Court rule in *Brown v. Board of Education of Topeka* (1954)?', '["State-sanctioned racial segregation in public schools was inherently unequal and violated the Equal Protection Clause of the 14th Amendment","Affirmed the ''separate but equal'' doctrine of Plessy v. Ferguson","Required busing in northern universities exclusively","Outlawed poll taxes in federal elections"]'::jsonb, 'Chief Justice Earl Warren''s unanimous ruling overturned *Plessy v. Ferguson*, declaring that separate educational facilities are inherently unequal.'),
  ('ap-topic-afam-hist_q5', 'ap-topic-afam-hist', 5, false, 'A', 'African American History', 'medium', 'What strategy did Dr. Martin Luther King Jr. and the SCLC employ to dismantle Jim Crow segregation?', '["Nonviolent direct action, peaceful protests, sit-ins, boycotts, and moral persuasion to expose racial injustice","Armed guerrilla insurrection in rural counties","Boycotting all federal tax payments","Relying exclusively on private courtroom lawsuits without public protests"]'::jsonb, 'Inspired by Mahatma Gandhi and Christian nonviolence, King mobilized public conscience through marches, speeches, and civil disobedience.'),
  ('ap-topic-afam-hist_q6', 'ap-topic-afam-hist', 6, false, 'A', 'African American History', 'medium', 'What was the purpose of the Freedom Rides organized by CORE and SNCC in 1961?', '["To test and enforce federal court orders banning racial segregation on interstate buses and in terminal facilities","To register voters in northern industrial cities","To build schools across Appalachia","To march on Washington for labor rights"]'::jsonb, 'Freedom Riders rode integrated interstate buses across the Deep South, enduring violent attacks to force federal desegregation enforcement.'),
  ('ap-topic-afam-hist_q7', 'ap-topic-afam-hist', 7, false, 'A', 'African American History', 'medium', 'What did the Voting Rights Act of 1965 accomplish?', '["It outlawed discriminatory voting literacy tests and established federal oversight of voter registration in jurisdictions with histories of racial disenfranchisement","It granted citizenship to Indigenous peoples","It eliminated the poll tax in state elections","It required paper ballots in all fifty states"]'::jsonb, 'Signed by President Lyndon B. Johnson, the Voting Rights Act protected minority voting access and dramatically increased Black voter registration.'),
  ('ap-topic-afam-hist_q8', 'ap-topic-afam-hist', 8, false, 'A', 'African American History', 'medium', 'Who were the founders of the Black Panther Party for Self-Defense in Oakland, California (1966)?', '["Huey P. Newton and Bobby Seale","Malcolm X and Elijah Muhammad","Marcus Garvey and W.E.B. Du Bois","Stokely Carmichael and H. Rap Brown"]'::jsonb, 'Newton and Seale founded the Black Panthers to monitor police brutality and provide community social survival programs (e.g. Free Breakfast for Children).'),
  ('ap-topic-afam-hist_q9', 'ap-topic-afam-hist', 9, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'What was the historical significance of the Stono Rebellion of 1739 in colonial South Carolina?', '["It was the largest slave insurrection in the British mainland colonies prior to the Revolutionary War, leading directly to the punitive South Carolina Negro Act of 1740","It led to the immediate emancipation of all enslaved laborers in South Carolina","It resulted in South Carolina declaring independence from the British Empire","It was a nonviolent boycott of British goods led by Free Black merchants"]'::jsonb, 'Enslaved leader Jemmy led approximately 80 rebels marching toward Spanish Florida (which offered freedom). In the aftermath, South Carolina enacted the Negro Act of 1740, severely restricting enslaved literacy, assembly, and autonomous movement.'),
  ('ap-topic-afam-hist_q10', 'ap-topic-afam-hist', 10, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'How did enslaved African Americans preserve and adapt cultural traditions despite the brutal constraints of chattel slavery?', '["Through spirituals, ring shouts, call-and-response oral music traditions, syncretic religious practices, and extended kinship networks","By completely adopting European classical music and abandoning all ancestral rhythms","By publishing printed legal journals in southern plantation houses","By founding commercial banks in coastal Virginia ports"]'::jsonb, 'Enslaved people forged vibrant syncretic cultures: covert religious ring shouts, coded spirituals ("Go Down, Moses", "Steal Away"), and fictive kinship networks provided resilience, mutual aid, and covert resistance.'),
  ('ap-topic-afam-hist_q11', 'ap-topic-afam-hist', 11, false, 'A', 'Movements, Culture & Freedom Struggles', 'hard', 'In his landmark 1852 address "What to the Slave Is the Fourth of July?", what was Frederick Douglass''s central moral indictment of the United States?', '["He exposed the profound national hypocrisy of celebrating liberty and independence while maintaining the brutal enslavement of millions of Black Americans","He argued that the Fourth of July should be permanently outlawed as a national holiday","He demanded the immediate partition of the United States into two separate nations","He urged all Black Americans to emigrate immediately to West Africa"]'::jsonb, 'Invited to address the Rochester Ladies'' Anti-Slavery Society, Douglass lauded the nation''s revolutionary principles but sharply contrasted white Americans'' freedom with the continued injustice and torture endured by enslaved Black people.'),
  ('ap-topic-afam-hist_q12', 'ap-topic-afam-hist', 12, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'How did Harriet Tubman contribute to the abolitionist movement during the antebellum era?', '["She repeatedly returned to the South as a \"conductor\" on the Underground Railroad, guiding dozens of enslaved people to freedom in the North and Canada","She served as the chief justice of the Massachusetts Supreme Court","She financed the purchase of the New York Tribune newspaper","She led the peaceful negotiation of the Missouri Compromise"]'::jsonb, 'Having escaped enslavement herself in 1849, Tubman returned at immense personal risk at least 13 times, never losing a passenger on the Underground Railroad, and later served as a Union scout, spy, and nurse in the Civil War.'),
  ('ap-topic-afam-hist_q13', 'ap-topic-afam-hist', 13, false, 'A', 'Movements, Culture & Freedom Struggles', 'hard', 'What was the philosophical disagreement between Booker T. Washington and W.E.B. Du Bois regarding African American advancement during the Jim Crow era?', '["Washington advocated vocational education and economic self-reliance while accommodating social segregation (the Atlanta Compromise); Du Bois demanded immediate civil rights, political enfranchisement, and higher education for the \"Talented Tenth\"","Washington advocated violent armed revolution; Du Bois advocated emigration to Liberia","Du Bois supported racial disenfranchisement; Washington founded the NAACP","Both leaders agreed that higher education was completely unnecessary for Black Americans"]'::jsonb, 'In the 1895 Atlanta Exposition address, Washington counseled patience and industrial craftsmanship. Du Bois countered in *The Souls of Black Folk* (1903), demanding full constitutional equality, voting rights, and liberal arts education for the "Talented Tenth," co-founding the Niagara Movement and NAACP.'),
  ('ap-topic-afam-hist_q14', 'ap-topic-afam-hist', 14, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'What was the Great Migration (beginning around World War I) and what were its primary driving factors?', '["The relocation of millions of African Americans from the rural South to urban industrial centers in the North and West, driven by violent Jim Crow oppression, boll weevil crop destruction, and wartime industrial labor shortages","The mass emigration of freedpeople to the American Southwest following the Civil War","The involuntary deportation of Black workers by federal authorities","The return of northern urban African Americans to southern agriculture"]'::jsonb, 'Between 1916 and 1970, over 6 million African Americans migrated North and West. Push factors included lynching, segregation, and disenfranchisement; pull factors included industrial factory jobs and greater educational opportunities.'),
  ('ap-topic-afam-hist_q15', 'ap-topic-afam-hist', 15, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'What cultural movement flourished in the 1920s celebrating African American artistic, musical, and literary heritage in Upper Manhattan?', '["Harlem Renaissance","Transcendentalist Movement","Beat Generation","Black Arts Movement of the 1960s"]'::jsonb, 'The Harlem Renaissance (the "New Negro" movement) fostered extraordinary cultural creativity in jazz (Duke Ellington, Louis Armstrong), literature (Langston Hughes, Zora Neale Hurston, Claude McKay), and visual art (Aaron Douglas).'),
  ('ap-topic-afam-hist_q16', 'ap-topic-afam-hist', 16, false, 'A', 'Movements, Culture & Freedom Struggles', 'hard', 'What legal principle was established by the Supreme Court in *Brown v. Board of Education of Topeka* (1954), argued by NAACP Legal Defense Fund counsel Thurgood Marshall?', '["State-mandated racial segregation in public schools violates the Equal Protection Clause of the Fourteenth Amendment because \"separate educational facilities are inherently unequal\"","Schools could remain racially segregated provided that funding per pupil was mathematically equal","The federal government had no authority to intervene in local school board policies","Affirmative action admissions policies were unconstitutional"]'::jsonb, 'Unanimously overturning the 1896 *Plessy v. Ferguson* "separate but equal" doctrine in public education, Chief Justice Earl Warren ruled that state-sanctioned racial segregation inflicts psychological harm and inherently violates the Fourteenth Amendment.'),
  ('ap-topic-afam-hist_q17', 'ap-topic-afam-hist', 17, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'What nonviolent direct-action protest sparked the Montgomery Bus Boycott of 1955-1956, elevating Dr. Martin Luther King Jr. to national prominence?', '["Rosa Parks refusing to surrender her bus seat to a white passenger in accordance with local Jim Crow transit ordinances","A student sit-in at a Woolworth''s lunch counter in Greensboro","The March on Washington for Jobs and Freedom","The Freedom Rides organized by CORE through the Deep South"]'::jsonb, 'NAACP activist Rosa Parks''s arrest for refusing to yield her seat sparked a 381-day community-wide bus boycott led by the Montgomery Improvement Association under Dr. King, culminating in *Browder v. Gayle* outlawing bus segregation.'),
  ('ap-topic-afam-hist_q18', 'ap-topic-afam-hist', 18, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'What were the major legislative achievements of the Civil Rights Movement passed during the Lyndon B. Johnson administration in 1964 and 1965?', '["The Civil Rights Act of 1964 (banning discrimination in public accommodations and employment) and the Voting Rights Act of 1965 (outlawing literacy tests and providing federal election oversight)","The Thirteenth and Fourteenth Amendments to the Constitution","The Emancipation Proclamation and the Freedmen''s Bureau Act","The Fair Housing Act of 1968 and the Americans with Disabilities Act"]'::jsonb, 'The Civil Rights Act of 1964 dismantled Jim Crow public segregation and employment bias (Title VII). The Voting Rights Act of 1965 banned discriminatory literacy tests and mandated federal preclearance for covered jurisdictions.'),
  ('ap-topic-afam-hist_q19', 'ap-topic-afam-hist', 19, false, 'A', 'Movements, Culture & Freedom Struggles', 'hard', 'What was the core platform of the Black Panther Party for Self-Defense, founded in Oakland in 1966 by Huey P. Newton and Bobby Seale?', '["Armed community self-defense against police brutality, paired with socialist community survival programs (such as Free Breakfast for Children and health clinics)","Complete integration into the Democratic Party leadership structure","Advocating total pacifism and non-resistance in all civil matters","Supporting the immediate return of all African Americans to West Africa"]'::jsonb, 'The Black Panthers published a Ten-Point Program demanding full employment, decent housing, education, and an end to police brutality, while providing free health clinics and educational breakfast programs in urban communities.'),
  ('ap-topic-afam-hist_q20', 'ap-topic-afam-hist', 20, false, 'A', 'Movements, Culture & Freedom Struggles', 'medium', 'What investigative journalism and anti-lynching crusade was pioneered by Ida B. Wells in the 1890s in publications like *Southern Horrors*?', '["Documenting and exposing that lynchings were not responses to criminal acts, but terrorist economic and political retaliation against Black success and autonomy","Advocating that Black sharecroppers surrender their land to white landlords","Promoting the exclusion of women from voting rights organizations","Publishing agricultural manuals on cotton cultivation techniques"]'::jsonb, 'Following the lynching of three friends in Memphis, Ida B. Wells conducted groundbreaking investigative journalism proving that allegations of rape were pretexts used by white supremacists to justify extrajudicial terror against prosperous Black competitors.')
